package com.projetok.prototype;

/**
 * Testes rápidos sem bibliotecas externas, executáveis com javac/java para validar
 * a simulação em ambientes sem Maven. O conjunto JUnit é definido separadamente.
 */
public final class DebugWorldSelfTest {
    private static final float STEP = 1f / 30f;

    private DebugWorldSelfTest() { }

    public static void main(String[] args) {
        validatesSetup();
        validatesNormalizedMovement();
        validatesWallAndObjectCollisions();
        validatesCombatAndCooldown();
        validatesMobAttack();
        validatesDeathEventAndImmutableSnapshot();
        System.out.println("OK: 6 validacoes do mundo 2D passaram.");
    }

    private static void validatesSetup() {
        DebugWorld world = new DebugWorld();
        DebugSnapshot s = world.snapshot();
        check(s.actors().size() == 4, "deve haver 1 jogador e 3 mobs");
        check(s.actors().get(0).player(), "o primeiro ator deve ser jogador");
        check(s.playerHp() == 100 && s.playerMaxHp() == 100, "HP derivado da raca humana");
        check(s.obstacles().size() == 3, "mapa deve possuir tres obstaculos");
    }

    private static void validatesNormalizedMovement() {
        DebugWorld horizontal = new DebugWorld();
        DebugWorld diagonal = new DebugWorld();
        float x0 = horizontal.snapshot().actors().get(0).x();
        horizontal.tick(new DebugInput(false, false, false, true, false), STEP);
        diagonal.tick(new DebugInput(true, false, false, true, false), STEP);
        var h = horizontal.snapshot().actors().get(0);
        var d = diagonal.snapshot().actors().get(0);
        float hDistance = h.x() - x0;
        float dDistance = (float) Math.hypot(d.x() - x0, d.y() - 340);
        check(Math.abs(hDistance - dDistance) < .02f, "diagonal nao pode ser mais rapida");
        check(horizontal.snapshot().ticks() == 1L, "tick deve ser contabilizado");
    }

    private static void validatesWallAndObjectCollisions() {
        DebugWorld world = new DebugWorld();
        for (int i = 0; i < 200; i++) {
            world.tick(new DebugInput(false, false, false, true, false), STEP);
            DebugSnapshot s = world.snapshot();
            DebugSnapshot.ActorView p = s.actors().get(0);
            check(p.x() >= DebugWorld.PLAYER_RADIUS && p.x() <= DebugWorld.WIDTH - DebugWorld.PLAYER_RADIUS,
                    "jogador saiu dos limites horizontais");
            for (DebugSnapshot.Obstacle o : s.obstacles()) {
                float closestX = Math.max(o.x(), Math.min(p.x(), o.x() + o.width()));
                float closestY = Math.max(o.y(), Math.min(p.y(), o.y() + o.height()));
                float distance = (float) Math.hypot(p.x() - closestX, p.y() - closestY);
                check(distance >= DebugWorld.PLAYER_RADIUS - .01f,
                        "jogador atravessou parede: " + distance);
            }
            for (DebugSnapshot.ActorView mob : s.actors()) {
                if (mob.player() || !mob.alive()) continue;
                float distance = (float) Math.hypot(p.x() - mob.x(), p.y() - mob.y());
                check(distance >= p.radius() + mob.radius() - .01f,
                        "jogador atravessou hitbox do mob");
            }
        }
    }

    private static void validatesCombatAndCooldown() {
        DebugWorld world = new DebugWorld();
        boolean inflictedDamage = false;
        DebugSnapshot current = world.snapshot();
        for (int i = 0; i < 360; i++) {
            var player = current.actors().get(0);
            var mob = current.actors().get(1);
            float dx = mob.x() - player.x();
            float dy = mob.y() - player.y();
            DebugInput input = new DebugInput(dy < -4, dy > 4, dx < -4, dx > 4, true);
            world.tick(input, STEP);
            DebugSnapshot next = world.snapshot();
            if (next.actors().get(1).hp() < mob.maxHp()) {
                inflictedDamage = true;
                int oldHp = next.actors().get(1).hp();
                check(oldHp == mob.maxHp() - 15,
                        "dano desarmado deve vir do CombatService e strength/2");
                // Um tick extra não pode ignorar o cooldown, mesmo segurando ESPAÇO.
                world.tick(new DebugInput(false, false, false, false, true), STEP);
                check(world.snapshot().actors().get(1).hp() == oldHp, "cooldown nao respeitado");
                break;
            }
            current = next;
        }
        check(inflictedDamage, "jogador deve conseguir acertar um mob e causar dano");
    }

    private static void validatesMobAttack() {
        DebugWorld world = new DebugWorld();
        boolean hit = false;
        for (int i = 0; i < 210; i++) {
            world.tick(DebugInput.NONE, STEP);
            if (world.snapshot().playerHp() < 100) { hit = true; break; }
        }
        check(hit, "mob deve perseguir jogador e atacar atraves do CombatService");
    }

    private static void validatesDeathEventAndImmutableSnapshot() {
        DebugWorld world = new DebugWorld();
        var snapshot = world.snapshot();
        boolean immutable = false;
        try { snapshot.actors().clear(); }
        catch (UnsupportedOperationException expected) { immutable = true; }
        check(immutable, "a interface nao pode alterar listas do dominio");
        boolean defeated = false;
        for (int i = 0; i < 600; i++) {
            var s = world.snapshot();
            var p = s.actors().get(0);
            var mob = s.actors().get(1);
            float dx = mob.x() - p.x(), dy = mob.y() - p.y();
            boolean moving = Math.hypot(dx, dy) > 49;
            world.tick(new DebugInput(moving && dy < -4, moving && dy > 4,
                    moving && dx < -4, moving && dx > 4, true), STEP);
            if (world.snapshot().defeated() >= 1) { defeated = true; break; }
        }
        check(defeated, "golpes repetidos devem causar morte e evento uma unica vez");
        for (int i = 0; i < 30; i++) world.tick(new DebugInput(false, false, false, false, true), STEP);
        check(world.snapshot().defeated() == 1, "evento de morte nao pode duplicar");
    }

    private static void check(boolean value, String description) {
        if (!value) throw new AssertionError(description);
    }
}

package com.projetok.prototype;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Testes JUnit 5 de regras visíveis do protótipo, sem abrir janela ou banco. */
class DebugWorldTest {
    private static final float TICK = 1f / 30f;

    /** Valida o reuso de PlayerFactory/MobFactory e os HPs raciais derivados. */
    @Test
    void criaJogadorETresInimigosComHpDerivado() {
        DebugSnapshot s = new DebugWorld().snapshot();
        assertEquals(4, s.actors().size());
        assertEquals(100, s.playerHp());
        assertEquals(120, s.actors().get(1).maxHp());
    }

    /** Movimento diagonal usa vetor normalizado, nunca gera velocidade extra. */
    @Test
    void normalizaVelocidadeDiagonal() {
        DebugWorld straight = new DebugWorld();
        DebugWorld diagonal = new DebugWorld();
        straight.tick(new DebugInput(false, false, false, true, false), TICK);
        diagonal.tick(new DebugInput(true, false, false, true, false), TICK);
        var a = straight.snapshot().actors().get(0);
        var b = diagonal.snapshot().actors().get(0);
        assertEquals(a.x() - 135f, Math.hypot(b.x() - 135f, b.y() - 340f), 0.01f);
    }

    /** Colisão mantém o centro do jogador fora de retângulos sólidos. */
    @Test
    void naoAtravessaObstaculos() {
        DebugWorld world = new DebugWorld();
        for (int n = 0; n < 180; n++) {
            world.tick(new DebugInput(false, false, false, true, false), TICK);
            DebugSnapshot s = world.snapshot();
            var p = s.actors().get(0);
            for (var o : s.obstacles()) {
                float closestX = Math.max(o.x(), Math.min(o.x() + o.width(), p.x()));
                float closestY = Math.max(o.y(), Math.min(o.y() + o.height(), p.y()));
                assertTrue(Math.hypot(p.x() - closestX, p.y() - closestY)
                        >= DebugWorld.PLAYER_RADIUS - .01f);
            }
        }
    }

    /** IA se aproxima de um alvo e utiliza o sistema de dano do dominio. */
    @Test
    void mobsCausamDanoAoJogador() {
        DebugWorld world = new DebugWorld();
        for (int i = 0; i < 210 && world.snapshot().playerHp() == 100; i++)
            world.tick(DebugInput.NONE, TICK);
        assertTrue(world.snapshot().playerHp() < 100);
    }

    /** Ataca com dano derivado do combate existente, aplicando cooldown de golpe. */
    @Test
    void aplicaDanoRealEImpedeAtaquesSemCooldown() {
        DebugWorld world = new DebugWorld();
        DebugSnapshot before = world.snapshot();
        boolean hit = false;
        for (int n = 0; n < 360; n++) {
            var p = before.actors().get(0);
            var mob = before.actors().get(1);
            float dx = mob.x() - p.x(), dy = mob.y() - p.y();
            world.tick(new DebugInput(dy < -4, dy > 4, dx < -4, dx > 4, true), TICK);
            DebugSnapshot after = world.snapshot();
            if (after.actors().get(1).hp() < 120) {
                assertEquals(105, after.actors().get(1).hp());
                world.tick(new DebugInput(false, false, false, false, true), TICK);
                assertEquals(105, world.snapshot().actors().get(1).hp());
                hit = true;
                break;
            }
            before = after;
        }
        assertTrue(hit, "Deve existir um caminho real de ataque até o mob");
    }

    /** Alcance e cone continuam impedindo dano mesmo quando há animação. */
    @Test
    void preservaAlcanceEConeDoAtaque() {
        DebugWorld distant = new DebugWorld();
        distant.tick(new DebugInput(false, false, false, false, true), TICK);
        assertNotNull(distant.snapshot().attack());
        assertEquals(120, distant.snapshot().actors().get(1).hp());

        DebugWorld world = new DebugWorld();
        for (int i = 0; i < 150; i++) {
            var s = world.snapshot();
            var p = s.actors().get(0);
            var m = s.actors().get(1);
            if (Math.hypot(m.x() - p.x(), m.y() - p.y()) <= 80) break;
            world.tick(DebugInput.NONE, TICK);
        }
        var before = world.snapshot();
        var p = before.actors().get(0);
        var m = before.actors().get(1);
        assertTrue(Math.hypot(m.x() - p.x(), m.y() - p.y()) <= 80);
        world.tick(new DebugInput(false, true, false, false, true), TICK);
        assertEquals(120, world.snapshot().actors().get(1).hp());
        assertEquals(1f, world.snapshot().attack().facingY());
    }
    @Test
    void corteNoArRespeitaCooldownDirecaoEExpiracao() {
        DebugWorld world = new DebugWorld();
        assertNull(world.snapshot().attack());
        world.tick(new DebugInput(true, false, false, true, true), TICK);
        var first = world.snapshot().attack();
        assertNotNull(first);
        assertEquals(Math.sqrt(0.5), first.facingX(), 0.0001);
        assertEquals(-Math.sqrt(0.5), first.facingY(), 0.0001);
        assertTrue(world.snapshot().effects().isEmpty());
        world.tick(new DebugInput(false, true, true, false, true), TICK);
        var next = world.snapshot().attack();
        assertEquals(first.facingX(), next.facingX());
        assertEquals(first.x(), next.x());
        assertTrue(next.remaining() < first.remaining());
        for (int i = 0; i < 5; i++) world.tick(DebugInput.NONE, TICK);
        assertNull(world.snapshot().attack());
        for (int i = 0; i < 6; i++) world.tick(DebugInput.NONE, TICK);
        world.tick(new DebugInput(false, false, false, false, true), TICK);
        assertNotNull(world.snapshot().attack());
        assertTrue(world.snapshot().attack().facingX() < 0);
    }

    @Test
    void renderizaCorteEmTodasAsDirecoesSemJanela() {
        boolean[][] directions = {{true,false,false,false}, {false,true,false,false},
                {false,false,true,false}, {false,false,false,true}, {true,false,false,true}};
        for (boolean[] d : directions) {
            DebugWorld world = new DebugWorld();
            world.tick(new DebugInput(d[0], d[1], d[2], d[3], true), TICK);
            var image = new java.awt.image.BufferedImage(DebugPanel.PANEL_WIDTH,
                    DebugPanel.PANEL_HEIGHT, java.awt.image.BufferedImage.TYPE_INT_ARGB);
            var g = image.createGraphics();
            try {
                new DebugPanel(world::snapshot).render(g, world.snapshot());
            } finally { g.dispose(); }
        }
    }
}

