package com.projetok.prototype;

import java.awt.geom.Point2D;

/** Transformacao pura; sem relogio, entidades ou estado de camera acumulado. */
public record ArenaViewport(double originX, double originY, int zoom,
                            double scale, double offsetX, double offsetY) {
    public ArenaViewport {
        if(!Double.isFinite(originX+originY+scale+offsetX+offsetY) || scale<=0 || zoom<1 || zoom>4)
            throw new IllegalArgumentException("Viewport invalida");
    }
    /** Canvas completo preserva HUD; camera recorta apenas a arena logica. */
    public static ArenaViewport fit(int screenWidth,int screenHeight,int worldWidth,int worldHeight,
                                    double targetX,double targetY,int zoom) {
        if(screenWidth<=0 || screenHeight<=0 || worldWidth<DebugWorld.WIDTH || worldHeight<DebugWorld.HEIGHT ||
                !Double.isFinite(targetX+targetY) || zoom<1 || zoom>4) throw new IllegalArgumentException("Limites invalidos");
        double fit=Math.min((double)screenWidth/DebugPanel.PANEL_WIDTH,(double)screenHeight/DebugPanel.PANEL_HEIGHT);
        double scale=fit>=1?Math.floor(fit):fit;
        double visibleW=(double)DebugWorld.WIDTH/zoom,visibleH=(double)DebugWorld.HEIGHT/zoom;
        double x=Math.floor(Math.max(0,Math.min(worldWidth-visibleW,targetX-visibleW/2)));
        double y=Math.floor(Math.max(0,Math.min(worldHeight-visibleH,targetY-visibleH/2)));
        return new ArenaViewport(x,y,zoom,scale,(screenWidth-DebugPanel.PANEL_WIDTH*scale)/2,
                (screenHeight-DebugPanel.PANEL_HEIGHT*scale)/2);
    }
    public Point2D.Double worldToScreen(double x,double y) {
        return new Point2D.Double(offsetX+(x-originX)*zoom*scale,offsetY+(y-originY)*zoom*scale);
    }
    public Point2D.Double screenToWorld(double x,double y) {
        return new Point2D.Double((x-offsetX)/(zoom*scale)+originX,(y-offsetY)/(zoom*scale)+originY);
    }
    public boolean containsScreen(double x,double y) {
        return x>=offsetX && y>=offsetY && x<offsetX+DebugWorld.WIDTH*scale && y<offsetY+DebugWorld.HEIGHT*scale;
    }
    /** Retângulo visível no mundo; HUD e letterbox não fazem parte da arena. */
    public java.awt.geom.Rectangle2D.Double visibleWorld() {
        return new java.awt.geom.Rectangle2D.Double(originX,originY,
                (double)DebugWorld.WIDTH/zoom,(double)DebugWorld.HEIGHT/zoom);
    }
}

package com.projetok.prototype;

import com.projetok.domain.command.SimulationCommandQueue;
import java.util.Objects;
import java.util.List;
import java.util.ArrayList;
import com.projetok.domain.skill.SkillCastCommand;

/** Adapta transições locais para um lote determinístico consumido em cada tick. */
final class DebugCommandBuffer {
    private interface Command { }
    private record Input(DebugInput value) implements Command { }
    private record Restart() implements Command { }
    private record Cast(SkillCastCommand value) implements Command { }

    /** Estado do tick, quantidade de novas pressões de E e marcador de reinício. */
    record Frame(DebugInput input, int effortPresses, boolean restart, List<SkillCastCommand> casts) { }

    private final SimulationCommandQueue<Command> queue = new SimulationCommandQueue<>();
    private DebugInput held = DebugInput.NONE;

    /** Publica transição; chamadas repetidas com E mantido não criam novas pressões. */
    void submit(DebugInput input) { queue.submit(new Input(Objects.requireNonNull(input))); }

    /** Ordena reinício junto às entradas, eliminando ações anteriores a ele. */
    void restart() { queue.submit(new Restart()); }

    /** Publica intenção de lançamento no mesmo contrato e fila das demais ações. */
    void cast(SkillCastCommand command) { queue.submit(new Cast(Objects.requireNonNull(command))); }

    /**
     * Executado somente pela thread da simulação. Toque de movimento dura um tick;
     * ataques rápidos respeitam o cooldown e cada pressão de E é contada uma vez.
     */
    Frame drain() {
        boolean up = false, down = false, left = false, right = false;
        boolean attack = false, restart = false;
        int effortPresses = 0;
        List<SkillCastCommand> casts = new ArrayList<>();
        for (Command command : queue.drain()) {
            if (command instanceof Restart) {
                restart = true;
                effortPresses = 0;
                casts.clear();
                up = false; down = false; left = false; right = false;
                attack = false;
            } else if (command instanceof Cast cast) {
                casts.add(cast.value());
            } else if (command instanceof Input input) {
                DebugInput next = input.value();
                if (next.effort() && !held.effort()) effortPresses++;
                up |= next.up() && !held.up(); down |= next.down() && !held.down();
                left |= next.left() && !held.left(); right |= next.right() && !held.right();
                attack |= next.attack() && !held.attack();
                held = next;
            }
        }
        return new Frame(new DebugInput(up || held.up(), down || held.down(),
                left || held.left(), right || held.right(), attack || held.attack(), held.effort()),
                effortPresses, restart, List.copyOf(casts));
    }
}

package com.projetok.prototype;

/**
 * Estado de entrada de um cliente local, coletado pela interface e lido pelo loop.
 * Nenhuma classe de domínio depende de Swing ou de eventos de teclado.
 */
public record DebugInput(boolean up, boolean down, boolean left, boolean right, boolean attack,
                         boolean effort) {
    /** Mantém compatibilidade com entradas anteriores, sem esforço físico. */
    public DebugInput(boolean up, boolean down, boolean left, boolean right, boolean attack) {
        this(up, down, left, right, attack, false);
    }
    public static final DebugInput NONE = new DebugInput(false, false, false, false, false);
}

package com.projetok.prototype;

import javax.swing.AbstractAction;
import javax.swing.ActionMap;
import javax.swing.InputMap;
import javax.swing.JComponent;
import javax.swing.JFrame;
import javax.swing.KeyStroke;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import java.awt.event.ActionEvent;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.HashSet;
import java.util.Set;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import com.projetok.domain.skill.SkillCastCommand;
import com.projetok.domain.skill.CryostasisService;
import com.projetok.domain.skill.LightningStepService;

/**
 * Executável do protótipo visual. Não substitui KServer.main nem o login real.
 * Execução: mvn -q exec:java -Dexec.mainClass=com.projetok.prototype.DebugLauncher
 */
public final class DebugLauncher {
    private DebugLauncher() { }

    public static void main(String[] args) {
        if (args.length == 0) SwingUtilities.invokeLater(DebugLauncher::open);
        else if (args.length == 2 && "--map".equals(args[0])) {
            try {
                LocalArenaMap map = LocalArenaMap.load(java.nio.file.Path.of(args[1]));
                SwingUtilities.invokeLater(() -> open(map));
            } catch (java.io.IOException error) { throw new IllegalArgumentException("Nao foi possivel carregar mapa local", error); }
        } else throw new IllegalArgumentException("Uso: DebugLauncher [--map arquivo.properties]");
    }

    /** Cria a interface no EDT e inicia a simulação em uma thread separada. */
    private static void open() {
        open(null);
    }

    /** Variante explicita de teste: R reutiliza os mesmos dados de mapa validados. */
    private static void open(LocalArenaMap map) {
        DebugRuntime runtime = map == null ? new DebugRuntime() : new DebugRuntime(
                () -> DebugWorld.forMap(map, java.util.random.RandomGenerator.getDefault()));
        DebugPanel panel = new DebugPanel(runtime::snapshot);
        panel.setLocalMap(map);
        panel.setPresentation(runtime::presentation, ValidatedSpriteAtlas.loadOptional(defaultVisualManifest()));
        JFrame frame = new JFrame("Spirit Gate | Arena de Debug 2D");
        frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
        frame.setContentPane(panel);
        frame.setResizable(true);
        frame.pack();
        frame.setLocationRelativeTo(null);
        Set<String> held = new HashSet<>();
        Runnable releaseInput = configureKeys(panel, runtime, held);
        frame.addWindowListener(new WindowAdapter() {
            @Override public void windowClosed(WindowEvent e) {
                runtime.close();
            }
            @Override public void windowDeactivated(WindowEvent e) {
                releaseInput.run();
            }
        });
        frame.addWindowFocusListener(new WindowAdapter() {
            @Override public void windowLostFocus(WindowEvent e) { releaseInput.run(); }
        });
        runtime.start();
        Timer paintTimer = new Timer(16, e -> panel.repaint());
        paintTimer.start();
        frame.addWindowListener(new WindowAdapter() {
            @Override public void windowClosed(WindowEvent e) { paintTimer.stop(); }
        });
        frame.setVisible(true);
    }

    // --- Atalhos: Key Bindings funcionam melhor que KeyListener ao trocar foco ---

    /** Pacote portatil resolve a arte junto ao EXE, independente do diretorio corrente. */
    static java.nio.file.Path defaultVisualManifest() {
        String launcher = System.getProperty("jpackage.app-path");
        java.nio.file.Path base = launcher == null ? java.nio.file.Path.of("") :
                java.nio.file.Path.of(launcher).toAbsolutePath().getParent();
        return base.resolve("visual/character.properties");
    }

    /** Liga teclas ao estado de entrada; acessível aos testes sem criar JFrame. */
    static Runnable configureKeys(DebugPanel panel, DebugRuntime runtime, Set<String> held) {
        InputMap inputs = panel.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW);
        ActionMap actions = panel.getActionMap();
        float[] aim = {Float.NaN, Float.NaN};
        panel.addMouseMotionListener(new MouseAdapter() {
            @Override public void mouseMoved(MouseEvent event) { aim[0] = event.getX(); aim[1] = event.getY(); }
            @Override public void mouseDragged(MouseEvent event) { mouseMoved(event); }
        });
        panel.addMouseListener(new MouseAdapter() {
            @Override public void mouseExited(MouseEvent event) { aim[0] = Float.NaN; aim[1] = Float.NaN; }
        });
        bindKey(inputs, "Q", "press_Q", "release_Q");
        actions.put("press_Q", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent event) {
                if (held.add("Q")) {
                    var target=panel.aimAt(aim[0],aim[1]);
                    runtime.cast(new SkillCastCommand(CryostasisService.ID, (float)target.x, (float)target.y));
                }
            }
        });
        actions.put("release_Q", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent event) { held.remove("Q"); }
        });
        bindKey(inputs, "SHIFT", "press_SHIFT", "release_SHIFT");
        actions.put("press_SHIFT", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent event) {
                if (held.add("SHIFT")) {
                    var target=panel.aimAt(aim[0],aim[1]);
                    runtime.cast(new SkillCastCommand(LightningStepService.ID, (float)target.x, (float)target.y));
                }
            }
        });
        actions.put("release_SHIFT", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent event) { held.remove("SHIFT"); }
        });
        for (String key : new String[] {"W", "A", "S", "D", "SPACE", "E"}) {
            bindKey(inputs, key, "press_" + key, "release_" + key);
            actions.put("press_" + key, new AbstractAction() {
                @Override public void actionPerformed(ActionEvent e) {
                    held.add(key);
                    sendInput(runtime, held);
                }
            });
            actions.put("release_" + key, new AbstractAction() {
                @Override public void actionPerformed(ActionEvent e) {
                    held.remove(key);
                    sendInput(runtime, held);
                }
            });
        }
        bindKey(inputs, "H", "hitboxes", null);
        bindKey(inputs, "F1", "help", null);
        bindKey(inputs, "F2", "diagnostic", null);
        actions.put("diagnostic", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) {
                var chooser=new javax.swing.JFileChooser();
                chooser.setDialogTitle("Salvar diagnostico local - revise o JSON antes de compartilhar");
                chooser.setSelectedFile(new java.io.File("SpiritGate-diagnostico.zip"));
                if(chooser.showSaveDialog(panel)!=javax.swing.JFileChooser.APPROVE_OPTION)return;
                try {
                    DiagnosticReport.export(chooser.getSelectedFile().toPath(),runtime.snapshot(),
                            panel.getWidth(),panel.getHeight(),panel.hasLocalMap(),DiagnosticReport.Stage.ARENA,null);
                    javax.swing.JOptionPane.showMessageDialog(panel,"ZIP local criado. Revise diagnostico.json antes de compartilhar.");
                } catch(java.io.IOException | IllegalArgumentException error) {
                    javax.swing.JOptionPane.showMessageDialog(panel,"Nao foi possivel criar o ZIP. Escolha um nome novo em pasta gravavel.");
                }
            }
        });
        actions.put("help", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { panel.toggleHelp(); }
        });
        actions.put("hitboxes", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) {
                panel.setShowHitboxes(!panel.isShowHitboxes());
            }
        });
        bindKey(inputs, "R", "restart", null);
        actions.put("restart", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) { runtime.restart(); }
        });
        return () -> {
            held.clear();aim[0]=Float.NaN;aim[1]=Float.NaN;
            runtime.setInput(DebugInput.NONE);
        };
    }

    /** Preserva os controles quando Shift aparece como modificador no evento Swing. */
    private static void bindKey(InputMap inputs, String key, String press, String release) {
        for (String prefix : new String[] {"", "shift "}) {
            inputs.put(KeyStroke.getKeyStroke(prefix + "pressed " + key), press);
            if (release != null) inputs.put(KeyStroke.getKeyStroke(prefix + "released " + key), release);
        }
    }

    private static void sendInput(DebugRuntime runtime, Set<String> held) {
        runtime.setInput(new DebugInput(held.contains("W"), held.contains("S"),
                held.contains("A"), held.contains("D"), held.contains("SPACE"), held.contains("E")));
    }
}

package com.projetok.prototype;

import javax.swing.JPanel;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Arc2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.function.Supplier;

/** Desenha uma visão descartável do mundo usando apenas Java2D (sem sprites externos). */
public final class DebugPanel extends JPanel {
    public static final int PANEL_WIDTH = DebugWorld.WIDTH + 300;
    public static final int PANEL_HEIGHT = DebugWorld.HEIGHT + 110;
    private static final Color BG = new Color(14, 22, 39);
    private static final Color TEXT = new Color(229, 239, 248);
    private static final Color ACCENT = new Color(70, 219, 235);
    private final Supplier<DebugSnapshot> source;
    private boolean showHitboxes;
    private boolean showHelp;
    private float ambientLight=1f;
    /** Opcao visual explicitamente desativada por padrao na arena historica. */
    public void setAmbientLight(float value) {
        if(!Float.isFinite(value)||value<0.5f||value>1f)throw new IllegalArgumentException("Luz invalida");ambientLight=value;
    }
    /** Alterna ajuda sem pausar ou enviar comandos ao mundo. */
    public void toggleHelp() { showHelp=!showHelp;repaint(); }
    public boolean isHelpVisible() { return showHelp; }
    boolean hasLocalMap() { return mapRenderer!=null; }
    /** Texto de apresentação usa somente os valores já publicados pela simulação. */
    static java.util.List<String> helpLines(DebugSnapshot snapshot) {
        return java.util.List.of("SPIRIT GATE - AJUDA (F1 para fechar)",
                "WASD: mover | ESPACO: golpe | E: vigor fisico",
                "SHIFT: Passo Relampago | Q: Criostase | mouse: mirar na arena",
                "R: reiniciar | H: hitboxes | F1: ajuda | F2: diagnostico local",
                "HP: vida | VIGOR: recurso para acoes e habilidades",
                "SHIFT atravessa obstaculos leves; solidos e bordas interrompem.",
                "Congelamento e recargas aparecem no HUD; mire fora do HUD.",
                "HP "+snapshot.playerHp()+"/"+snapshot.playerMaxHp()+" | VIGOR "+Math.round(snapshot.stamina())+"/"+Math.round(snapshot.maxStamina()),
                "Q: "+snapshot.cryostasisHud().stateText()+" | SHIFT: "+snapshot.lightningStepHud().stateText());
    }
    private Supplier<DirectionalAnimation.Presentation> presentationSource;
    private ValidatedSpriteAtlas spriteAtlas;
    private LocalArenaMap.Renderer mapRenderer;
    private int cameraZoom=1;
    private int worldWidth=DebugWorld.WIDTH, worldHeight=DebugWorld.HEIGHT;
    private boolean culling=true;
    /** Referência de comparação visual; não altera os dados da simulação. */
    public void setCulling(boolean enabled) { culling=enabled; }
    private boolean visible(Graphics2D g,double x,double y,double w,double h) {
        return !culling || g.hitClip((int)Math.floor(x),(int)Math.floor(y),
                (int)Math.ceil(w)+2,(int)Math.ceil(h)+2);
    }

    /** Zoom inteiro opcional; padrao preserva coordenadas historicas. */
    public void setCameraZoom(int zoom) {
        if(zoom<1 || zoom>4) throw new IllegalArgumentException("Zoom invalido");
        cameraZoom=zoom; repaint();
    }
    ArenaViewport viewport(DebugSnapshot snapshot) {
        var player=snapshot.actors().stream().filter(DebugSnapshot.ActorView::player).findFirst();
        double x=player.map(a->(double)a.x()).orElse(480d),y=player.map(a->(double)a.y()).orElse(320d);
        return ArenaViewport.fit(getWidth()>0?getWidth():PANEL_WIDTH,getHeight()>0?getHeight():PANEL_HEIGHT,
                worldWidth,worldHeight,x,y,cameraZoom);
    }
    /** Conversao no instante do comando evita mira obsoleta se a camera se moveu. */
    java.awt.geom.Point2D.Double aimAt(float x,float y) {
        var v=viewport(source.get());
        return v.containsScreen(x,y)?v.screenToWorld(x,y):new java.awt.geom.Point2D.Double(Double.NaN,Double.NaN);
    }

    /** Seletor visual opcional de demonstracao, sem modificar o mundo a partir da imagem. */
    public void setLocalMap(LocalArenaMap map) {
        mapRenderer = map == null ? null : map.renderer();
        worldWidth = map == null ? DebugWorld.WIDTH : map.width();
        worldHeight = map == null ? DebugWorld.HEIGHT : map.height();
    }

    /** Ativa somente um atlas ja validado; null mantem a geometria original. */
    public void setPresentation(Supplier<DirectionalAnimation.Presentation> source, ValidatedSpriteAtlas atlas) {
        presentationSource = source;
        spriteAtlas = atlas;
    }

    public DebugPanel(Supplier<DebugSnapshot> source) {
        this.source = source;
        setPreferredSize(new Dimension(PANEL_WIDTH, PANEL_HEIGHT));
        setBackground(BG);
        setDoubleBuffered(true);
        setFocusable(true);
    }

    /** Permite inspecionar raio físico e alcance do ataque sem alterar a simulação. */
    public void setShowHitboxes(boolean visible) {
        this.showHitboxes = visible;
        repaint();
    }

    public boolean isShowHitboxes() { return showHitboxes; }

    @Override
    protected void paintComponent(Graphics original) {
        super.paintComponent(original);
        Graphics2D g = (Graphics2D) original.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            if (presentationSource == null) render(g, source.get());
            else render(g, presentationSource.get());
        } finally {
            g.dispose();
        }
    }

    /** Renderização pura a partir de um snapshot: também é utilizada no smoke visual. */
    public void render(Graphics2D g, DebugSnapshot s) {
        renderScene(g, s, java.util.List.of());
    }

    /** Desenha valores do mesmo tick; o render nunca avanca o sequenciador. */
    public void render(Graphics2D g, DirectionalAnimation.Presentation presentation) {
        renderScene(g, presentation.world(), presentation.animations());
    }

    private void renderScene(Graphics2D g, DebugSnapshot s, java.util.List<DirectionalAnimation.View> animations) {
        var viewport=viewport(s);
        Graphics2D canvas=(Graphics2D)g.create();
        try {
        canvas.translate(viewport.offsetX(),viewport.offsetY());
        canvas.scale(viewport.scale(),viewport.scale());
        canvas.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        Graphics2D world=(Graphics2D)canvas.create();
        try {
        world.clipRect(0,0,DebugWorld.WIDTH,DebugWorld.HEIGHT);
        world.scale(viewport.zoom(),viewport.zoom());
        world.translate(-viewport.originX(),-viewport.originY());
        renderWorld(world,s,animations);
        if(ambientLight<1f){world.setColor(new Color(8,12,35,Math.round((1f-ambientLight)*255)));world.fillRect(0,0,worldWidth,worldHeight);}
        } finally {world.dispose();}
        drawSidebar(canvas,s);
        drawBottom(canvas,s);
        if(showHelp) {
            canvas.setColor(new Color(8,15,28,240));canvas.fillRoundRect(20,20,920,330,20,20);
            canvas.setColor(TEXT);canvas.setFont(new Font("SansSerif",Font.BOLD,16));
            int y=55;for(String line:helpLines(s)) {canvas.drawString(line,40,y);y+=31;}
        }
        } finally {canvas.dispose();}
    }

    private void renderWorld(Graphics2D g,DebugSnapshot s,java.util.List<DirectionalAnimation.View> animations) {
        drawWorld(g);
        if (mapRenderer != null) mapRenderer.drawLayers(g,0,4);
        drawObstacles(g, s);
        drawSoftObstacles(g, s);
        drawIceZones(g, s);
        drawLightningTrails(g, s);
        for (DebugSnapshot.ActorView actor : s.actors()) {
            // Margem inclui nome, barras, alcance, sprite/pivot e marca de Freeze.
            if(spriteAtlas==null && !visible(g,actor.x()-100,actor.y()-100,200,200)) continue;
            DirectionalAnimation.View visual = null;
            for (var candidate : animations) if (candidate.actorId() == actor.id()) { visual=candidate; break; }
            if (spriteAtlas == null || visual == null || !spriteAtlas.draw(g, actor, visual)) drawActor(g, actor, s);
        }
        if (mapRenderer != null) mapRenderer.drawLayers(g,5,10);
        drawAttack(g, s.attack());
        drawEffects(g, s);
    }

    // --- Cenário ---

    /** Rastro amarelo com desvanecimento a partir dos tempos publicados, sem timers da GUI. */
    private void drawLightningTrails(Graphics2D original, DebugSnapshot snapshot) {
        Graphics2D g = (Graphics2D) original.create();
        try {
            g.clipRect(0, 0, worldWidth, worldHeight);
            for (var trail : snapshot.lightningTrails()) {
                float alpha = Math.max(0, Math.min(1, trail.remaining() / trail.duration()));
                double dx = trail.x1() - trail.x0(), dy = trail.y1() - trail.y0();
                double length = Math.hypot(dx, dy);
                if (length == 0) continue;
                Path2D bolt = new Path2D.Double();
                bolt.moveTo(trail.x0(), trail.y0());
                for (int i = 1; i < 6; i++) {
                    double fraction = i / 6.0, offset = (i % 2 == 0 ? -1 : 1) * 3;
                    bolt.lineTo(trail.x0() + fraction * dx - dy / length * offset,
                            trail.y0() + fraction * dy + dx / length * offset);
                }
                bolt.lineTo(trail.x1(), trail.y1());
                g.setStroke(new BasicStroke(9f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.setColor(new Color(255, 205, 30, Math.round(alpha * 55)));
                g.draw(bolt);
                g.setStroke(new BasicStroke(2.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.setColor(new Color(255, 240, 110, Math.round(alpha * 245)));
                g.draw(bolt);
            }
        } finally { g.dispose(); }
    }

    /** Desenha gelo e pulsação apenas a partir do relógio publicado pela simulação. */
    private void drawIceZones(Graphics2D original, DebugSnapshot snapshot) {
        Graphics2D g = (Graphics2D) original.create();
        try {
            g.clipRect(0, 0, worldWidth, worldHeight);
            for (var zone : snapshot.iceZones()) {
                float r = zone.radius(), x = zone.x(), y = zone.y();
                float pulse = (float) (0.5 + 0.5 * Math.cos(zone.elapsed() * Math.PI * 4));
                g.setColor(new Color(125, 220, 255, 45 + Math.round(pulse * 20)));
                g.fill(new Ellipse2D.Float(x - r, y - r, r * 2, r * 2));
                g.setColor(new Color(190, 245, 255, 210));
                g.setStroke(new BasicStroke(3f));
                g.draw(new Ellipse2D.Float(x - r, y - r, r * 2, r * 2));
                g.setStroke(new BasicStroke(1.5f));
                g.setColor(new Color(165, 235, 255, 90));
                float ring = r * (0.65f + pulse * 0.15f);
                g.draw(new Ellipse2D.Float(x - ring, y - ring, ring * 2, ring * 2));
                for (int i = 0; i < 12; i++) {
                    double angle = i * Math.PI / 6;
                    float cx = x + (float) Math.cos(angle) * r * 0.92f;
                    float cy = y + (float) Math.sin(angle) * r * 0.92f;
                    g.drawLine(Math.round(cx - 4), Math.round(cy), Math.round(cx + 4), Math.round(cy));
                    g.drawLine(Math.round(cx), Math.round(cy - 4), Math.round(cx), Math.round(cy + 4));
                }
            }
        } finally { g.dispose(); }
    }

    /** Pinta solo, grade de referência e bordas da arena. */
    private void drawWorld(Graphics2D g) {
        g.setPaint(new GradientPaint(0, 0, new Color(27, 54, 63),
                worldWidth, worldHeight, new Color(12, 39, 52)));
        g.fillRect(0, 0, worldWidth, worldHeight);
        g.setColor(new Color(255, 255, 255, 12));
        for (int x = 0; x <= worldWidth; x += 40) g.drawLine(x, 0, x, worldHeight);
        for (int y = 0; y <= worldHeight; y += 40) g.drawLine(0, y, worldWidth, y);
        // Lâminas de grama decorativas, sem colisão: os obstáculos sólidos ficam explícitos.
        g.setStroke(new BasicStroke(2f));
        g.setColor(new Color(61, 126, 118, 90));
        for (int x = 28; x < worldWidth; x += 77) {
            for (int y = 32; y < worldHeight; y += 89) {
                g.drawLine(x, y, x - 4, y - 7);
                g.drawLine(x, y, x + 4, y - 6);
            }
        }
        g.setColor(new Color(98, 183, 176));
        g.setStroke(new BasicStroke(4f));
        g.drawRect(1, 1, worldWidth - 2, worldHeight - 2);
    }

    /** Desenha pedras/paredes e destaca suas bordas sólidas no modo de inspeção. */
    private void drawObstacles(Graphics2D g, DebugSnapshot world) {
        for (DebugSnapshot.Obstacle o : world.obstacles()) {
            if(!visible(g,o.x()-3,o.y()-3,o.width()+14,o.height()+16)) continue;
            int x = Math.round(o.x()), y = Math.round(o.y());
            int w = Math.round(o.width()), h = Math.round(o.height());
            g.setColor(new Color(0, 0, 0, 65));
            g.fillRoundRect(x + 8, y + 10, w, h, 18, 18);
            g.setPaint(new GradientPaint(x, y, new Color(86, 107, 116),
                    x + w, y + h, new Color(39, 60, 78)));
            g.fillRoundRect(x, y, w, h, 18, 18);
            g.setColor(new Color(127, 172, 172));
            g.setStroke(new BasicStroke(3f));
            g.drawRoundRect(x, y, w, h, 18, 18);
            g.setColor(new Color(192, 226, 218, 56));
            for (int yy = y + 22; yy < y + h - 10; yy += 32) {
                g.drawLine(x + 18, yy, x + w - 18, yy);
            }
            if (showHitboxes) {
                g.setColor(new Color(255, 190, 35, 200));
                g.setStroke(new BasicStroke(2f));
                g.drawRect(x, y, w, h);
            }
        }
    }

    /** Distingue arbustos e postes leves; H mostra exatamente o retângulo físico publicado. */
    private void drawSoftObstacles(Graphics2D g, DebugSnapshot world) {
        for (var obstacle : world.softObstacles()) {
            if(!visible(g,obstacle.x()-6,obstacle.y()-3,obstacle.width()+18,obstacle.height()+16)) continue;
            int x = Math.round(obstacle.x()), y = Math.round(obstacle.y());
            int width = Math.round(obstacle.width()), height = Math.round(obstacle.height());
            g.setColor(new Color(0, 0, 0, 65));
            g.fillOval(x - 4, y + height - 5, width + 12, 12);
            if (obstacle.kind() == DebugSnapshot.SoftObstacleKind.BUSH) {
                g.setColor(new Color(45, 106, 69));
                g.fillRoundRect(x, y, width, height, 20, 20);
                g.setColor(new Color(81, 157, 86));
                g.fillOval(x, y, width * 2 / 3, height * 2 / 3);
                g.fillOval(x + width / 3, y + height / 5, width * 2 / 3, height * 2 / 3);
                g.setColor(new Color(142, 197, 110));
