    /** Desenha somente o estado e o retorno já publicados; não decide elegibilidade. */
    private static void drawSkillHud(Graphics2D g, DebugSnapshot.SkillHudView hud, int y, Color accent) {
        g.setFont(new Font("SansSerif", Font.BOLD, 11));
        g.setColor(accent);
        String label = hud.key() + "  " + hud.label() + " | Mouse | " + Math.round(hud.cost()) + " vigor";
        g.drawString(label, 25, y);
        int stateX = 25 + g.getFontMetrics().stringWidth(label) + 16;
        g.setColor(switch (hud.state()) {
            case READY -> new Color(80, 219, 168);
            case COOLDOWN -> new Color(245, 171, 108);
            case INSUFFICIENT_STAMINA, DEAD -> new Color(250, 121, 121);
            case ACTIVE -> new Color(255, 235, 110);
            case AWAITING_LANDING -> new Color(255, 187, 85);
        });
        g.drawString(hud.stateText(), stateX, y);
        int feedbackX = stateX + g.getFontMetrics().stringWidth(hud.stateText()) + 16;
        g.setFont(new Font("SansSerif", Font.PLAIN, 11));
        g.setColor(new Color(205, 218, 227));
        g.drawString(hud.feedback().message(), feedbackX, y);
    }

    /** Pinta uma barra proporcional, limitando visualmente os valores entre 0 e 1. */
    private static void drawBar(Graphics2D g, int x, int y, int w, int h, float ratio, Color fill) {
        g.setColor(new Color(32, 46, 62));
        g.fillRoundRect(x, y, w, h, h, h);
        g.setColor(fill);
        g.fillRoundRect(x, y, Math.round(w * Math.max(0, Math.min(1, ratio))), h, h, h);
    }

    /** Centraliza texto sobre uma coordenada do mundo. */
    private static void center(Graphics2D g, String text, int centerX, int y) {
        FontMetrics metrics = g.getFontMetrics();
        g.drawString(text, centerX - metrics.stringWidth(text) / 2, y);
    }

    /** Divide mensagens longas para evitar cortar o log no painel lateral. */
    private static void textLines(Graphics2D g, String text, int x, int y, int lineHeight) {
        int limit = 29;
        String[] words = text.split(" ");
        StringBuilder line = new StringBuilder();
        for (String word : words) {
            if (line.length() + word.length() + 1 > limit) {
                g.drawString(line.toString(), x, y);
                y += lineHeight;
                line.setLength(0);
            }
            if (line.length() > 0) line.append(' ');
            line.append(word);
        }
        if (!line.isEmpty()) g.drawString(line.toString(), x, y);
    }
}

package com.projetok.prototype;

import com.projetok.domain.skill.SkillCastCommand;

import java.util.Objects;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

/**
 * Laço fixo a 30 ticks/segundo: somente sua thread acessa o mundo mutável.
 * Swing apenas publica entrada e lê snapshots completos (sem condições de corrida).
 */
public final class DebugRuntime implements AutoCloseable {
    private final ScheduledExecutorService gameThread = Executors.newSingleThreadScheduledExecutor(r -> {
        Thread thread = new Thread(r, "spirit-gate-simulation");
        thread.setDaemon(true);
        return thread;
    });
    private final DebugCommandBuffer commands = new DebugCommandBuffer();
    private final Supplier<DebugWorld> worldFactory;
    private volatile DebugWorld world;
    private volatile DebugSnapshot lastSnapshot;
    private final DirectionalAnimation animations = new DirectionalAnimation();
    private volatile DirectionalAnimation.Presentation presentation;

    /** Inicializa a arena demonstrativa usada pela janela e pelos reinícios. */
    public DebugRuntime() {
        this(DebugWorld::demo);
    }

    /** Permite sorteios reproduzíveis nos testes, inclusive depois do reinício. */
    DebugRuntime(Supplier<DebugWorld> worldFactory) {
        this.worldFactory = Objects.requireNonNull(worldFactory, "worldFactory");
        world = Objects.requireNonNull(worldFactory.get(), "world");
        lastSnapshot = world.snapshot();
        presentation = animations.advance(lastSnapshot, java.util.List.of(), 0);
    }

    /** Inicializa o loop local sem banco de dados ou serviço de rede. */
    public void start() {
        gameThread.scheduleAtFixedRate(() -> {
            try {
                advanceOneTick();
            } catch (RuntimeException exception) {
                System.err.println("[Spirit Gate] Falha no tick de debug:");
                exception.printStackTrace();
                throw exception; // falha visível; não finge que o mundo continua funcionando
            }
        }, 0, 33_333_333L, TimeUnit.NANOSECONDS);
    }

    /**
     * Processa o mesmo tick usado pelo agendador, sempre em uma única thread proprietária.
     * Testes do pacote podem avançá-lo sem iniciar o agendador nem consultar relógio real.
     */
    void advanceOneTick() {
        DebugCommandBuffer.Frame frame = commands.drain();
        if (frame.restart()) {
            animations.reset();
            world = Objects.requireNonNull(worldFactory.get(), "world");
            // O primeiro deslocamento apos R deve partir do spawn, como na abertura.
            animations.advance(world.snapshot(), java.util.List.of(), 0);
            world.synchronizeEffort(frame.input().effort());
        }
        world.tickQueued(frame.input(), 1f / 30f, frame.effortPresses(), frame.casts());
        lastSnapshot = world.snapshot();
        presentation = animations.advance(lastSnapshot, world.animationSignals(), 1d / 30d);
    }

    /** Recebe entrada do controlador sem modificar entidades fora do loop. */
    public void setInput(DebugInput value) {
        commands.submit(value);
    }

    /** Solicita a criação de uma nova arena na thread que possui o mundo. */
    public void restart() {
        commands.restart();
    }

    /** Transporta intenção imutável; entidades são alteradas somente no próximo tick. */
    public void cast(SkillCastCommand command) { commands.cast(command); }

    /** Último estado imutável publicado pelo loop, próprio para leitura no EDT. */
    public DebugSnapshot snapshot() {
        return presentation.world();
    }

    /** Mundo e animacoes do mesmo tick publicados em uma unica referencia imutavel. */
    public DirectionalAnimation.Presentation presentation() { return presentation; }

    @Override
    public void close() {
        gameThread.shutdownNow();
    }
}

package com.projetok.prototype;

import java.util.List;

/** Cópia imutável do estado do jogo, segura para consumo pela thread da interface. */
public record DebugSnapshot(
        List<ActorView> actors, List<Obstacle> obstacles, List<EffectView> effects,
        int playerHp, int playerMaxHp, int defeated, boolean gameOver, long ticks,
        String lastEvent, float facingX, float facingY, float cooldown, AttackView attack,
        float stamina, float maxStamina, float cryostasisCooldown, List<IceZoneView> iceZones,
        List<StatusView> statuses, boolean lightningStepActive, float lightningStepRemaining,
        float lightningStepCooldown, List<LightningTrailView> lightningTrails,
        boolean lightningStepAwaitingLanding, List<SoftObstacleView> softObstacles,
        SkillHudView cryostasisHud, SkillHudView lightningStepHud) {

    /** Copia os novos metadados visuais; a interface nunca recebe a lista mutável do mundo. */
    public DebugSnapshot {
        actors = List.copyOf(actors);
        obstacles = List.copyOf(obstacles);
        effects = List.copyOf(effects);
        iceZones = List.copyOf(iceZones);
        statuses = List.copyOf(statuses);
        lightningTrails = List.copyOf(lightningTrails);
        softObstacles = List.copyOf(softObstacles);
    }

    /** Disponibilidade calculada pela simulação, sem decisões de gameplay no painel. */
    public enum SkillState { READY, COOLDOWN, INSUFFICIENT_STAMINA, DEAD, ACTIVE, AWAITING_LANDING }

    /** Origem explícita do último retorno breve de uma habilidade. */
    public enum SkillFeedbackKind {
        NONE, ACCEPTED, INVALID_TARGET, DEAD, ZERO_DIRECTION, COOLDOWN,
        INSUFFICIENT_STAMINA, AWAITING_LANDING, SOLID_OR_BOUNDARY
    }

    /** Mensagem e duração copiadas da simulação; a interface não avança seu relógio. */
    public record SkillFeedbackView(SkillFeedbackKind kind, String message, float remaining) { }

    /** Linha pronta para renderização, com números e estado sem referências mutáveis. */
    public record SkillHudView(String skillId, String key, String label, float cost, float cooldown,
                               float stamina, SkillState state, String stateText,
                               SkillFeedbackView feedback) { }

    /** Aparências do demo; ambas usam retângulos explícitos de colisão leve. */
    public enum SoftObstacleKind { BUSH, POST }

    /** Hitbox publicada a partir da mesma geometria usada pela simulação. */
    public record SoftObstacleView(float x, float y, float width, float height, SoftObstacleKind kind) { }

    /** Segmento visual elétrico com tempo de vida; sem estado mutável da habilidade. */
    public record LightningTrailView(float x0, float y0, float x1, float y1,
                                     float remaining, float duration) { }

    /** Estado visual por ator, separado do contrato histórico de ActorView. */
    public record StatusView(int actorId, float freezeRemaining) { }

    /** Círculo visual fixo; somente valores, sem regras ou entidades. */
    public record IceZoneView(float x, float y, float radius, float elapsed, float duration) { }

    /** Informações suficientes para desenhar um personagem sem expor componentes mutáveis. */
    public record ActorView(int id, String name, float x, float y, float radius,
                            int hp, int maxHp, boolean player, boolean alive) { }

    /** Retângulo sólido no mapa em coordenadas de mundo (pixels de depuração). */
    public record Obstacle(float x, float y, float width, float height) { }

    /** Marcador visual transitório do resultado de um ataque. */
    public record AttackView(float x, float y, float facingX, float facingY, float remaining) { }

    /** Marcador visual transit?rio do resultado de um ataque. */
    public record EffectView(float x, float y, int damage, float remaining, boolean received) { }
}

