import com.projetok.domain.event.events.EntityDeathEvent;
import com.projetok.domain.factory.MobArchetype;
import com.projetok.domain.factory.MobFactory;
import com.projetok.domain.factory.PlayerArchetype;
import com.projetok.domain.factory.PlayerFactory;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.network.PlayerConnection;
import com.projetok.domain.progression.VitalityService;
import com.projetok.domain.race.RaceRegistry;

import java.util.ArrayList;
import java.util.List;

/**
 * Mundo mínimo AUTORITATIVO para prototipagem. Só a thread de simulação pode alterar
 * suas entidades; a interface recebe cópias imutáveis por meio de {@link #snapshot()}.
 * Não depende de Swing, de PostgreSQL nem de Kryonet. Um futuro adaptador de rede poderá
 * substituir DebugInput por comandos remotos mantendo as mesmas regras de colisão.
 */
public final class DebugWorld {

    public static final int WIDTH = 960;
    public static final int HEIGHT = 640;
    private final int worldWidth, worldHeight;

    /** Dimensões físicas do mapa atual; as constantes conservam o cenário histórico. */
    public int worldWidth() { return worldWidth; }
    public int worldHeight() { return worldHeight; }
    public static final float PLAYER_RADIUS = 18f;
    public static final float MOB_RADIUS = 19f;
    public static final float WALK_SPEED = 215f;
    public static final float MELEE_REACH = 74f;
    public static final float ATTACK_DURATION = 0.18f;
    private DebugSnapshot.AttackView attack;
    private static final float MOB_SPEED = 92f;
    private static final float MOB_AGGRO = 320f;
    private static final float MOB_MELEE = 58f;
    private static final float PLAYER_COOLDOWN = 0.38f;
    private static final float MOB_COOLDOWN = 1.15f;
    private static final float HALF_CONE_COS = 0.7071068f; // cone de 90 graus

    private final GameEventBus events = new GameEventBus();
    private final CombatService combat = new CombatService(events);
    private final CollisionService collisions = new CollisionService();
    private final MovementService movement;
    private final LightningStepService lightningStep;
    private final StaminaService staminaService = new StaminaService();
    private final StatusEffectService statusEffects = new StatusEffectService();
    private final CryostasisService cryostasis;
    private boolean effortHeld;
    private final Player player;
    private final List<Mob> mobs = new ArrayList<>();
    private final CollisionService.Space collisionSpace;
    private static final List<CollisionService.Obstacle> ORIGINAL_OBSTACLES = List.of(
            new CollisionService.Obstacle(346, 112, 110, 228),
            new CollisionService.Obstacle(594, 310, 112, 174),
            new CollisionService.Obstacle(275, 500, 145, 44));
    private final List<CollisionService.Obstacle> obstacles;
    private final List<DemoObstacle> softObstacles;

    /** Associa arte e corpo sem inferir a hitbox pelo tamanho do desenho. */
    private record DemoObstacle(CollisionService.Obstacle body, DebugSnapshot.SoftObstacleKind kind) { }

    // Área demonstrativa ao sul do ponto inicial; não altera o cenário histórico.
    private static final List<DemoObstacle> DEMO_OBSTACLES = List.of(
            new DemoObstacle(new CollisionService.Obstacle(70, 420, 36, 40,
                    CollisionCategory.SOFT_OBSTACLE), DebugSnapshot.SoftObstacleKind.BUSH),
            new DemoObstacle(new CollisionService.Obstacle(160, 420, 36, 40,
                    CollisionCategory.SOFT_OBSTACLE), DebugSnapshot.SoftObstacleKind.BUSH),
            new DemoObstacle(new CollisionService.Obstacle(250, 425, 14, 30,
                    CollisionCategory.SOFT_OBSTACLE), DebugSnapshot.SoftObstacleKind.POST));
    private final List<DebugSnapshot.EffectView> effects = new ArrayList<>();
    private final List<DebugSnapshot.LightningTrailView> lightningTrails = new ArrayList<>();
    private static final float TRAIL_DURATION = 0.18f;
    private static final float SKILL_FEEDBACK_DURATION = 1.2f;
    private DebugSnapshot.SkillFeedbackView cryostasisFeedback = SkillHudMapper.none();
    private DebugSnapshot.SkillFeedbackView lightningStepFeedback = SkillHudMapper.none();
    private final float[] enemyCooldowns = new float[3];
    private float facingX = 1f;
    private float facingY = 0f;
    private float attackCooldown;
    private long ticks;
    private final List<DirectionalAnimation.Signal> animationSignals = new ArrayList<>();

    /** Copia eventos reais do ultimo tick sem modificar o contrato historico do snapshot. */
    public List<DirectionalAnimation.Signal> animationSignals() { return List.copyOf(animationSignals); }
    private int defeated;
    private String lastEvent = "Explore a arena e derrote os tres espiritos.";

    /** Instancia jogador e mobs usando as fábricas reais do domínio existente. */
    public DebugWorld() {
        this(RandomGenerator.getDefault());
    }

    /** Permite reproduzir os sorteios de gameplay sem acoplar testes à interface. */
    public DebugWorld(RandomGenerator random) {
        this(random, MovementService.Response.SOFT_SLIDE);
    }

    /** Permite comparar a resposta nova com a referência histórica sem alterar os baselines. */
    public DebugWorld(RandomGenerator random, MovementService.Response response) {
        this(random, response, false);
    }

    /** Cria a arena jogável com dois arbustos e um poste de colisão leve. */
    public static DebugWorld demo() {
        return demo(RandomGenerator.getDefault());
    }

    /** Reproduz o cenário demonstrativo com sorteios controláveis nos testes. */
    public static DebugWorld demo(RandomGenerator random) {
        return new DebugWorld(random, MovementService.Response.SOFT_SLIDE, true);
    }

    /** Mantém os construtores históricos e compartilha toda a simulação entre os cenários. */
    private DebugWorld(RandomGenerator random, MovementService.Response response, boolean demo) {
        this(random, response, demo, null);
    }

    /** Variante isolada por dados locais; demo() e construtores historicos permanecem iguais. */
    public static DebugWorld forMap(LocalArenaMap map, RandomGenerator random) {
        return new DebugWorld(random, MovementService.Response.SOFT_SLIDE, false, java.util.Objects.requireNonNull(map));
    }

    private DebugWorld(RandomGenerator random, MovementService.Response response, boolean demo, LocalArenaMap map) {
        worldWidth = map == null ? WIDTH : map.width();
        worldHeight = map == null ? HEIGHT : map.height();
        softObstacles = map == null ? (demo ? DEMO_OBSTACLES : List.of()) : map.physical().stream()
                .filter(p -> p.category() == CollisionCategory.SOFT_OBSTACLE)
                .map(p -> new DemoObstacle(new CollisionService.Obstacle(p.x(),p.y(),p.width(),p.height(),p.category()),p.kind())).toList();
        List<CollisionService.Obstacle> geometry = new ArrayList<>(map == null ? ORIGINAL_OBSTACLES : map.obstacles().stream()
                .filter(p -> p.category() == CollisionCategory.SOLID_OBSTACLE).toList());
        softObstacles.forEach(obstacle -> geometry.add(obstacle.body()));
        obstacles = List.copyOf(geometry);
        movement = new MovementService(collisions, response);
        lightningStep = new LightningStepService(movement, staminaService, collisions,
                CollisionPolicy.PHASE_THROUGH_ACTORS_AND_SOFT);
        cryostasis = new CryostasisService(combat, staminaService, statusEffects, new ProbabilityService(random));
        RaceRegistry races = RaceRegistry.withDefaults();
        VitalityService vitality = new VitalityService();
        player = new PlayerFactory(vitality).create(1, "Guardiao", new PlayerArchetype(
                        races.get("human"), 30, 8, 14, null, null),
                new Position(map == null ? 135 : map.spawnX(), map == null ? 340 : map.spawnY()), new PlayerConnection() {
                    @Override public void send(Object packet) { /* canal local não envia pacotes */ }
                    @Override public void disconnect() { /* nenhum socket aberto */ }
                });
        MobFactory factory = new MobFactory(vitality);
        float[][] locations = {{215, 148}, {812, 190}, {782, 550}};
        for (int i = 0; i < locations.length; i++) {
            MobArchetype archetype = new MobArchetype(races.get("demon"),
                    "Espírito Errante " + (i + 1), 1, 12, 4, 9, null,
                    LootTable.of(), new PassiveBehavior());
            mobs.add(factory.spawn(100 + i, archetype,
                    new Position(locations[i][0], locations[i][1])));
        }
        List<CollisionService.Body> bodies = new ArrayList<>();
        bodies.add(new CollisionService.Body(player, PLAYER_RADIUS));
        for (Mob mob : mobs) bodies.add(new CollisionService.Body(mob, MOB_RADIUS));
        collisionSpace = new CollisionService.Space(worldWidth, worldHeight, obstacles, bodies,
                new SpatialBodyIndex(bodies, 96f));
        events.subscribe(EntityDeathEvent.class, event -> {
            if (event.entity() == player) {
                lastEvent = "Voce caiu! Pressione R para reiniciar.";
            } else {
                defeated++;
                lastEvent = event.entity().getName() + " derrotado!";
            }
        });
    }

    /**
     * Executa um frame determinístico, com delta em segundos; só deve ser chamado
     * pelo proprietário do estado do mundo. Input nunca inclui posição absoluta.
     */
    public void tick(DebugInput input, float dt) {
        tickQueued(input, dt, -1);
    }

    /** Processa pressões conservadas pela fila; -1 mantém detecção por estado para chamadas antigas. */
    void tickQueued(DebugInput input, float dt, int effortPresses) {
        tickQueued(input, dt, effortPresses, List.of());
    }

    /** Coordena comandos de skill sem alterar a API anterior de entrada. */
    void tickQueued(DebugInput input, float dt, int effortPresses, List<SkillCastCommand> casts) {
        if (!Float.isFinite(dt) || dt <= 0f || dt > 0.1f) throw new IllegalArgumentException("dt fora do intervalo (0, 0.1]");
        ticks++;
        animationSignals.clear();
        // Retornos do HUD têm relógio próprio e não substituem o log histórico da arena.
        cryostasisFeedback = SkillHudMapper.elapse(cryostasisFeedback, dt);
        lightningStepFeedback = SkillHudMapper.elapse(lightningStepFeedback, dt);
        // Efeitos antigos avançam antes dos pulsos: um novo sucesso conserva 1 s inteiro.
        for (Mob mob : mobs) statusEffects.update(mob, dt);
        if (attack != null) {
            float remaining = attack.remaining() - dt;
            attack = remaining <= 0f ? null : new DebugSnapshot.AttackView(
                    attack.x(), attack.y(), attack.facingX(), attack.facingY(), remaining);
        }
        attackCooldown = Math.max(0f, attackCooldown - dt);
        for (int i = 0; i < enemyCooldowns.length; i++) {
            enemyCooldowns[i] = Math.max(0f, enemyCooldowns[i] - dt);
        }
        for (int i = effects.size() - 1; i >= 0; i--) {
            var effect = effects.get(i);
            float remaining = effect.remaining() - dt;
            if (remaining <= 0) effects.remove(i);
            else effects.set(i, new DebugSnapshot.EffectView(effect.x(), effect.y(),
                    effect.damage(), remaining, effect.received()));
        }
        for (int i = lightningTrails.size() - 1; i >= 0; i--) {
            var trail = lightningTrails.get(i);
            float remaining = trail.remaining() - dt;
            if (remaining <= 0) lightningTrails.remove(i);
            else lightningTrails.set(i, new DebugSnapshot.LightningTrailView(
                    trail.x0(), trail.y0(), trail.x1(), trail.y1(), remaining, trail.duration()));
        }
        publishHits(cryostasis.update(dt, cryostasisTargets()));
        boolean dashingAtStart = lightningStep.active() || lightningStep.awaitingLanding();
        var dashStep = lightningStep.update(player, dt, PLAYER_RADIUS, collisionSpace);
        if (dashStep.moved()) addLightningTrail(dashStep);
        // A política seletiva ignora atores e leves: redução real só indica sólido ou borda.
        if (dashStep.blocked()) lightningStepFeedback = SkillHudMapper.blockedFeedback(SKILL_FEEDBACK_DURATION);
        if (player.isDead()) return;
        staminaService.regenerate(player, dt);
        int activations = effortPresses >= 0 ? effortPresses : (input.effort() && !effortHeld ? 1 : 0);
        effortHeld = input.effort();
        // O tick fracionário final ainda pertence ao dash; WASD retorna no próximo tick.
        if (!dashingAtStart) movePlayer(input, dt);
        if (input.attack()) attackNearest();
        for (SkillCastCommand command : casts) {
            // Um único laço preserva a ordem de Q/Shift e o saldo compartilhado de vigor.
            if (command != null && LightningStepService.ID.equals(command.skillId())) {
                var status = lightningStep.cast(player, command, PLAYER_RADIUS, collisionSpace);
                lightningStepFeedback = SkillHudMapper.feedback(status, SKILL_FEEDBACK_DURATION);
                lastEvent = switch (status) {
                    case STARTED -> "Passo Relampago iniciado: 35 de vigor.";
                    case INVALID -> "Passo Relampago: alvo invalido.";
                    case DEAD -> "Passo Relampago: jogador derrotado.";
                    case ZERO_DIRECTION -> "Passo Relampago: escolha uma direcao.";
                    case COOLDOWN -> "Passo Relampago em recarga.";
                    case STAMINA -> "Vigor insuficiente para Passo Relampago (35).";
                    case LANDING_PENDING -> "Passo Relampago: aguardando uma saida livre.";
                };
                continue;
            }
            var result = cryostasis.cast(player, command, worldWidth, worldHeight, cryostasisTargets());
            cryostasisFeedback = SkillHudMapper.feedback(result.status(), SKILL_FEEDBACK_DURATION);
            lastEvent = switch (result.status()) {
                case CAST -> "Criostase lancada: zona de gelo ativa.";
                case INVALID -> "Criostase: alvo ou habilidade invalida.";
                case DEAD -> "Criostase: jogador derrotado.";
                case COOLDOWN -> "Criostase em recarga.";
                case STAMINA -> "Vigor insuficiente para Criostase (55).";
            };
            publishHits(result.hits());
        }
        updateEnemies(dt);
        if (!player.isDead()) for (int i = 0; i < activations; i++) performEffort();
    }

    /** Registra só trechos realmente percorridos, incluindo a curva X/Y da física. */
    private void addLightningTrail(LightningStepService.Step step) {
        for (int i = 1; i < step.path().size(); i++) {
            var from = step.path().get(i - 1); var to = step.path().get(i);
            if (!from.equals(to)) lightningTrails.add(new DebugSnapshot.LightningTrailView(
                    from.x(), from.y(), to.x(), to.y(), TRAIL_DURATION, TRAIL_DURATION));
        }
    }

    /** Fornece hitboxes dos mobs; a skill consulta vida e posição em cada pulso. */
    private List<CryostasisService.Target> cryostasisTargets() {
        return mobs.stream().map(mob -> new CryostasisService.Target(mob, MOB_RADIUS)).toList();
    }

    /** Publica os danos já aplicados por CombatService e preserva feedback de morte. */
    private void publishHits(List<CryostasisService.Hit> hits) {
        for (var hit : hits) {
            addEffect(hit.mob(), hit.damage(), false);
            if (hit.mob().isDead()) lastEvent = hit.mob().getName() + " derrotado!";
        }
    }

    // --- Vigor físico: ação temporária, sem dano ---

    /** Sincroniza a tecla ao reiniciar para exigir uma nova pressão após soltá-la. */
    void synchronizeEffort(boolean held) {
        effortHeld = held;
    }

    /** Verifica o custo antes de executar a ação provisória de esforço. */
    private void performEffort() {
        if (staminaService.tryConsume(player, 20f)) {
            lastEvent = "Esforco fisico realizado: 20 de vigor.";
        } else {
            lastEvent = "Vigor insuficiente para esforco fisico (20).";
        }
    }

    // --- Movimento e colisões ---

    /** Normaliza diagonais, move por eixos e respeita paredes, objetos e atores. */
    private void movePlayer(DebugInput input, float dt) {
        float x = (input.right() ? 1 : 0) - (input.left() ? 1 : 0);
        float y = (input.down() ? 1 : 0) - (input.up() ? 1 : 0);
        if (x == 0f && y == 0f) return;
        Position direction = movement.direction(x, y);
        x = direction.x();
        y = direction.y();
        facingX = x;
        facingY = y;
        movement.moveDirected(player, direction, WALK_SPEED, dt, PLAYER_RADIUS, collisionSpace());
    }

    /** Consulta posições atuais entre movimentos sequenciais dos atores. */
    private CollisionService.Space collisionSpace() {
        return collisionSpace;
    }

    // --- Elegibilidade de combate e dano delegado ao domínio ---

    /** Aplica cooldown, distância e cone ANTES de chamar CombatService.attack. */
    private void attackNearest() {
        if (attackCooldown > 0f) return;
        attackCooldown = PLAYER_COOLDOWN;
        animationSignals.add(new DirectionalAnimation.Signal(player.getId(), DirectionalAnimation.State.ATTACK));
        Mob closest = null;
        float best = Float.POSITIVE_INFINITY;
        Position origin = player.getPosition();
        attack = new DebugSnapshot.AttackView(origin.x(), origin.y(), facingX, facingY, ATTACK_DURATION);
        for (Mob mob : mobs) {
            if (mob.isDead()) continue;
            Position target = mob.getPosition();
            float dx = target.x() - origin.x();
            float dy = target.y() - origin.y();
            float length = (float) Math.hypot(dx, dy);
            if (length > MELEE_REACH + MOB_RADIUS || length < 0.0001f) continue;
            float dot = (dx * facingX + dy * facingY) / length;
            if (dot < HALF_CONE_COS) continue;
            if (length < best) {
                closest = mob;
                best = length;
            }
        }
        if (closest != null) {
            int amount = combat.attack(player, closest);
            addEffect(closest, amount, false);
            lastEvent = "Golpe desarmado: " + amount + " de dano.";
            if (closest.isDead()) lastEvent = closest.getName() + " derrotado!";
        } else {
            lastEvent = "Golpe no ar: aproxime-se e olhe para o alvo.";
        }
    }

    /** IA mínima: perseguição, colisão contra cenário e ataque corpo a corpo. */
    private void updateEnemies(float dt) {
        for (int i = 0; i < mobs.size(); i++) {
            Mob mob = mobs.get(i);
            if (mob.isDead() || player.isDead()) continue;
            Position p = mob.getPosition();
            Position target = player.getPosition();
            float dx = target.x() - p.x();
            float dy = target.y() - p.y();
            float length = (float) Math.hypot(dx, dy);
            if (length < MOB_AGGRO && length > MOB_MELEE - 2) {
                movement.moveDirected(mob, new Position(dx / length, dy / length),
                        MOB_SPEED, dt, MOB_RADIUS, collisionSpace());
            }
            p = mob.getPosition();
            length = (float) Math.hypot(target.x() - p.x(), target.y() - p.y());
            if (length <= MOB_MELEE && enemyCooldowns[i] <= 0f) {
                enemyCooldowns[i] = MOB_COOLDOWN;
                animationSignals.add(new DirectionalAnimation.Signal(mob.getId(), DirectionalAnimation.State.ATTACK));
                int amount = combat.attack(mob, player);
                addEffect(player, amount, true);
                lastEvent = mob.getName() + " atingiu voce: " + amount + " de dano.";
                if (player.isDead()) lastEvent = "Voce caiu! Pressione R para reiniciar.";
            }
        }
    }

    /** Registra um efeito de dano temporário sem alterar a regra de HP. */
    private void addEffect(GameEntity target, int amount, boolean received) {
        if (amount > 0) animationSignals.add(new DirectionalAnimation.Signal(target.getId(), DirectionalAnimation.State.HIT));
        effects.add(new DebugSnapshot.EffectView(target.getPosition().x(),
                target.getPosition().y() - 25, amount, 0.7f, received));
    }

    // --- Leitura por cópia para a interface ---

    /** Publica apenas valores: nunca a referência mutável do jogador ou dos mobs. */
    public DebugSnapshot snapshot() {
        List<DebugSnapshot.ActorView> actors = new ArrayList<>();
        actors.add(view(player, PLAYER_RADIUS, true));
        for (Mob mob : mobs) actors.add(view(mob, MOB_RADIUS, false));
        HealthComponent hp = player.require(HealthComponent.class);
        float vigor = player.require(StaminaComponent.class).current();
        return new DebugSnapshot(List.copyOf(actors), obstacles.stream().filter(o -> o.category() == CollisionCategory.SOLID_OBSTACLE).map(o ->
                        new DebugSnapshot.Obstacle(o.x(), o.y(), o.width(), o.height())).toList(), List.copyOf(effects),
                hp.current(), hp.max(), defeated, player.isDead(), ticks,
                lastEvent, facingX, facingY, attackCooldown, attack,
                player.require(StaminaComponent.class).current(),
                player.require(StaminaComponent.class).max(), cryostasis.cooldown(),
                cryostasis.zones().stream().map(zone -> new DebugSnapshot.IceZoneView(
                        zone.x(), zone.y(), CryostasisZone.RADIUS, zone.elapsed(), CryostasisZone.DURATION)).toList(),
                mobs.stream().filter(mob -> !mob.isDead()).filter(mob -> mob.require(StatusEffectsComponent.class)
                        .has(StatusEffectType.FREEZE)).map(mob -> new DebugSnapshot.StatusView(mob.getId(),
                        mob.require(StatusEffectsComponent.class).remaining(StatusEffectType.FREEZE))).toList(),
                lightningStep.active(), lightningStep.remaining(), lightningStep.cooldown(), List.copyOf(lightningTrails),
                lightningStep.awaitingLanding(), softObstacles.stream().map(obstacle -> {
                    var body = obstacle.body();
                    return new DebugSnapshot.SoftObstacleView(body.x(), body.y(), body.width(), body.height(),
                            obstacle.kind());
                }).toList(),
                SkillHudMapper.cryostasis(player.isDead(), vigor, cryostasis.cooldown(), cryostasisFeedback),
                SkillHudMapper.lightningStep(player.isDead(), vigor, lightningStep.cooldown(),
                        lightningStep.active(), lightningStep.awaitingLanding(), lightningStepFeedback));
    }

    /** Extrai apenas os campos visuais de uma entidade do domínio. */
    private static DebugSnapshot.ActorView view(GameEntity entity, float radius, boolean player) {
        HealthComponent hp = entity.require(HealthComponent.class);
        return new DebugSnapshot.ActorView(entity.getId(), entity.getName(),
                entity.getPosition().x(), entity.getPosition().y(), radius,
                hp.current(), hp.max(), player, !hp.isDead());
    }

}

package com.projetok.prototype;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/** Diagnóstico local por lista permitida; nunca lê ambiente, nomes ou caminhos pessoais. */
public final class DiagnosticReport {
    public static final String VERSION="0.36.0-rc1";
    public enum Stage { ARENA, MAP_LOADING, RENDERING }
    private DiagnosticReport() { }

    /** Não inclui lastEvent, nomes de atores, mensagens/stack de exceção ou nome do mapa. */
    public static String json(DebugSnapshot snapshot,int width,int height,boolean localMap,Stage stage,Throwable error) {
        if(width<=0 || height<=0 || width>32768 || height>32768 || stage==null)
            throw new IllegalArgumentException("Dimensoes/etapa invalidas");
        // Valores de propriedades passam por listas fechadas, sem exportar propriedades arbitrárias.
        String os=System.getProperty("os.name","").toLowerCase(java.util.Locale.ROOT);
        os=os.startsWith("windows")?"Windows":os.startsWith("linux")?"Linux":os.startsWith("mac")?"macOS":"Other";
        String arch=System.getProperty("os.arch","");
        arch=arch.equals("amd64") || arch.equals("x86_64")?"x64":arch.equals("aarch64")?"arm64":"other";
        String jvm=System.getProperty("java.version","");
        if(!jvm.matches("[0-9][0-9.+_-]{0,40}"))jvm="unknown";
        return "{\n  \"schemaVersion\": 1,\n  \"version\": \""+VERSION+"\",\n  \"os\": \""+os+"\",\n"+
                "  \"arch\": \""+arch+"\",\n  \"jvm\": \""+jvm+"\",\n  \"window\": ["+width+","+height+"],\n"+
                "  \"map\": \""+(localMap?"LOCAL_MAP":"DEFAULT_ARENA")+"\",\n  \"stage\": \""+stage+"\",\n"+
                "  \"error\": \""+(error==null?"NONE":"REPORTED_ERROR_DETAILS_OMITTED")+"\",\n"+
                "  \"ticks\": "+snapshot.ticks()+",\n  \"actors\": "+snapshot.actors().size()+",\n"+
                "  \"hp\": "+snapshot.playerHp()+",\n  \"gameOver\": "+snapshot.gameOver()+",\n"+
                "  \"cryostasisState\": \""+snapshot.cryostasisHud().state()+"\",\n"+
                "  \"dashState\": \""+snapshot.lightningStepHud().state()+"\"\n}\n";
    }

    /** Exportação explícita e exclusiva; um único JSON revisável, sem arquivos externos. */
    public static void export(Path destination,DebugSnapshot snapshot,int width,int height,boolean localMap,Stage stage,Throwable error) throws IOException {
        byte[] data=json(snapshot,width,height,localMap,stage,error).getBytes(StandardCharsets.UTF_8);
        try(var zip=new ZipOutputStream(Files.newOutputStream(destination,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE))) {
            var entry=new ZipEntry("diagnostico.json");entry.setTime(0);zip.putNextEntry(entry);
            zip.write(data);zip.closeEntry();
        }
    }
}

package com.projetok.prototype;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/** Sequenciador visual exclusivo da simulacao; nao altera entidades nem usa relogio real. */
public final class DirectionalAnimation {
    public enum State { IDLE, WALK, RUN, ATTACK, HIT, FAINT }
    public enum Direction { FRONT, BACK, LEFT, RIGHT }
    /** Sinal de combate emitido no ponto real da simulacao, nunca inferido da cor. */
    public record Signal(int actorId, State state) { }
    /** Apenas valores imutaveis sao entregues ao renderizador. */
    public record View(int actorId, State state, Direction direction, int frame) { }
    /** Publicacao atomica do mundo e de seus estados visuais correspondentes. */
    public record Presentation(DebugSnapshot world, List<View> animations) {
        public Presentation { animations = List.copyOf(animations); }
    }
    private record Track(DebugSnapshot.ActorView actor, State state, Direction direction, double elapsed) { }
    private final Map<Integer, Track> tracks = new HashMap<>();

    /** Descarta facing e tempos ao recriar o mundo por R. */
    public void reset() { tracks.clear(); }

    /** Avanca exclusivamente pelo dt recebido; dt zero pausa a apresentacao. */
    public Presentation advance(DebugSnapshot world, List<Signal> signals, double dt) {
        if (!Double.isFinite(dt) || dt < 0 || dt > .1) throw new IllegalArgumentException("dt visual invalido");
        List<View> result = new ArrayList<>(world.actors().size());
        for (var actor : world.actors()) {
            Track old = tracks.get(actor.id());
            double dx = old == null ? 0 : actor.x()-old.actor().x();
            double dy = old == null ? 0 : actor.y()-old.actor().y();
            Direction direction = facing(dx, dy, old == null ? Direction.FRONT : old.direction());
            if (actor.player()) direction = facing(world.facingX(), world.facingY(), direction);
            boolean frozen = world.statuses().stream().anyMatch(s -> s.actorId()==actor.id() && s.freezeRemaining()>0);
            State state = dx*dx+dy*dy > .000001 ? State.WALK : State.IDLE;
            if (old != null && (old.state()==State.HIT || old.state()==State.ATTACK) && old.elapsed()+dt < duration(old.state())) state=old.state();
            boolean triggered = false;
            for (Signal signal : signals) if (signal.actorId()==actor.id()) {
                if (signal.state()==State.HIT || state!=State.HIT) state=signal.state();
                triggered=true;
            }
            if (!actor.alive()) { state=State.FAINT; direction=Direction.FRONT; }
            else if (frozen && old != null && !triggered) state=old.state();
            double elapsed = old == null || old.state()!=state || old.direction()!=direction || triggered ? 0 : old.elapsed()+(frozen ? 0 : dt);
            Track next = new Track(actor,state,direction,elapsed);
            tracks.put(actor.id(),next);
            result.add(new View(actor.id(),state,direction,frame(state,elapsed)));
        }
        tracks.keySet().retainAll(world.actors().stream().map(DebugSnapshot.ActorView::id).toList());
        return new Presentation(world,result);
    }

    /** Eixo dominante, empate vertical estavel e ultimo facing quando parado. */
    public static Direction facing(double x, double y, Direction previous) {
        if (x*x+y*y < .000001) return previous;
        return Math.abs(x)>Math.abs(y) ? (x>0 ? Direction.RIGHT : Direction.LEFT) : (y>0 ? Direction.FRONT : Direction.BACK);
    }
    public static int count(State state) {
        return switch(state) { case IDLE -> 1; case WALK, RUN -> 4; case ATTACK, FAINT -> 3; case HIT -> 2; };
    }
    public static double duration(State state) { return count(state)*.1; }
    private static int frame(State state, double elapsed) {
        int index=(int)Math.floor((elapsed+1e-8)/.1);
        return state==State.FAINT || state==State.HIT || state==State.ATTACK ? Math.min(count(state)-1,index) : index%count(state);
    }
}

package com.projetok.prototype;

import com.projetok.domain.movement.CollisionCategory;
import com.projetok.domain.movement.CollisionService;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Properties;
import java.util.Set;

/** Mapa local versionado: aparencia nunca define a geometria autoritativa. */
public record LocalArenaMap(int width, int height, float spawnX, float spawnY,
                            List<Visual> visuals, List<Physical> physical) {
    /** Placeholder sintetico; tamanho e camada nao alteram a hitbox. */
    public record Visual(String id, int x, int y, int width, int height, int layer, int rgb) { }
    /** Retangulo fisico explicitamente tipado; WORLD_BOUNDARY e o limite do mundo. */
    public record Physical(String id, float x, float y, float width, float height,
                           CollisionCategory category, DebugSnapshot.SoftObstacleKind kind) { }

    public LocalArenaMap {
        visuals=List.copyOf(visuals);physical=List.copyOf(physical);
        if(width<DebugWorld.WIDTH || height<DebugWorld.HEIGHT || width>8192 || height>8192)
            throw new IllegalArgumentException("Limites do mundo: 960x640 ate 8192x8192");
        if(visuals.size()>4096 || physical.size()>4096) throw new IllegalArgumentException("Contagem excessiva");
        Set<String> ids=new HashSet<>();
        for(var v:visuals) {
            if(v.id()==null || v.id().isBlank() || !ids.add(v.id())) throw new IllegalArgumentException("ID visual duplicado/vazio");
            try { bounds(v.x(),v.y(),v.width(),v.height(),width,height); }
            catch(IllegalArgumentException e) {throw new IllegalArgumentException("visual "+v.id()+": x/y/width/height invalidos",e);}
            if(v.layer()<0 || v.layer()>10 || v.rgb()<0 || v.rgb()>0xffffff) throw new IllegalArgumentException("Camada/cor invalida");
        }
        ids.clear();int boundaries=0;
        for(var p:physical) {
            if(p.id()==null || p.id().isBlank() || !ids.add(p.id())) throw new IllegalArgumentException("ID fisico duplicado/vazio");
            try { bounds(p.x(),p.y(),p.width(),p.height(),width,height); }
            catch(IllegalArgumentException e) {throw new IllegalArgumentException("physical "+p.id()+": x/y/width/height invalidos",e);}
            if(p.category()==CollisionCategory.WORLD_BOUNDARY) {
                boundaries++;
                if(p.x()!=0 || p.y()!=0 || p.width()!=width || p.height()!=height) throw new IllegalArgumentException("Borda deve coincidir com mundo");
            } else if(p.category()!=CollisionCategory.SOFT_OBSTACLE && p.category()!=CollisionCategory.SOLID_OBSTACLE) throw new IllegalArgumentException("Categoria fisica invalida");
            if(p.category()==CollisionCategory.SOFT_OBSTACLE && p.kind()==null) throw new IllegalArgumentException("Leve exige tipo visual explicito");
        }
        if(boundaries!=1) throw new IllegalArgumentException("Exatamente uma borda explicita obrigatoria");
        List<Physical> bodies=physical.stream().filter(p->p.category()!=CollisionCategory.WORLD_BOUNDARY).toList();
        for(int i=0;i<bodies.size();i++) for(int j=i+1;j<bodies.size();j++) {
            var a=bodies.get(i);var b=bodies.get(j);
            if(a.x()<b.x()+b.width() && a.x()+a.width()>b.x() && a.y()<b.y()+b.height() && a.y()+a.height()>b.y()) throw new IllegalArgumentException("physical: sobreposicao "+a.id()+" / "+b.id());
        }
        float[][] spawns={{spawnX,spawnY,DebugWorld.PLAYER_RADIUS},{215,148,DebugWorld.MOB_RADIUS},{812,190,DebugWorld.MOB_RADIUS},{782,550,DebugWorld.MOB_RADIUS}};
        for(var s:spawns) {
            if(!Float.isFinite(s[0]) || !Float.isFinite(s[1]) || s[0]<s[2] || s[1]<s[2] || s[0]>width-s[2] || s[1]>height-s[2]) throw new IllegalArgumentException("Spawn fora do mapa");
            for(var b:bodies) {
                float dx=s[0]-Math.max(b.x(),Math.min(s[0],b.x()+b.width()));
                float dy=s[1]-Math.max(b.y(),Math.min(s[1],b.y()+b.height()));
                if(dx*dx+dy*dy<s[2]*s[2]) throw new IllegalArgumentException("Spawn ocupado");
            }
        }
        for(int i=0;i<spawns.length;i++) for(int j=i+1;j<spawns.length;j++) {
            float dx=spawns[i][0]-spawns[j][0],dy=spawns[i][1]-spawns[j][1],r=spawns[i][2]+spawns[j][2];
            if(dx*dx+dy*dy<r*r) throw new IllegalArgumentException("Spawns sobrepostos");
        }
    }
    private static void bounds(float x,float y,float w,float h,int width,int height) {
        if(!Float.isFinite(x+y+w+h) || x<0 || y<0 || w<=0 || h<=0 || x+w>width || y+h>height) throw new IllegalArgumentException("Retangulo fora dos limites");
    }
    /** Carrega apenas arquivo local Properties, com contagens limitadas e chaves estritas. */
    public static LocalArenaMap load(Path path) throws IOException {
        if(Files.size(path)>1_000_000) throw new IOException("Mapa excessivo");
        Properties p=new Properties() {
            @Override public synchronized Object put(Object key,Object value) {
                if(containsKey(key)) throw new IllegalArgumentException("Chave duplicada no mapa");
                return super.put(key,value);
            }
        };
        try(var reader=Files.newBufferedReader(path)) {p.load(reader);}
        try {
            String version=(String)p.remove("schemaVersion");
            if(!"1".equals(version) && !"2".equals(version)) throw new IllegalArgumentException("Schema desconhecido");
            int w=integer(p,"width"),h=integer(p,"height");
            if("1".equals(version) && (w!=960 || h!=640)) throw new IllegalArgumentException("V1 exige 960x640");
            if("2".equals(version) && w==960 && h==640) throw new IllegalArgumentException("V2 reservado a mapas ampliados; use V1 para 960x640");
            float sx=number(p,"spawnX"),sy=number(p,"spawnY");
            int nv=count(p,"visual.count"),np=count(p,"physical.count");
            List<Visual> visuals=new ArrayList<>();List<Physical> physical=new ArrayList<>();
            for(int i=0;i<nv;i++) {
                String prefix="visual."+i+".";
                visuals.add(new Visual(take(p,prefix+"id"),integer(p,prefix+"x"),integer(p,prefix+"y"),integer(p,prefix+"width"),integer(p,prefix+"height"),integer(p,prefix+"layer"),Integer.parseInt(take(p,prefix+"rgb"),16)));
            }
            for(int i=0;i<np;i++) {
                String prefix="physical."+i+".";
                String id=take(p,prefix+"id");float x=number(p,prefix+"x"),y=number(p,prefix+"y"),pw=number(p,prefix+"width"),ph=number(p,prefix+"height");
                CollisionCategory category=CollisionCategory.valueOf(take(p,prefix+"category"));
                String kind=(String)p.remove(prefix+"kind");
                physical.add(new Physical(id,x,y,pw,ph,category,kind==null?null:DebugSnapshot.SoftObstacleKind.valueOf(kind)));
            }
            if(!p.isEmpty()) throw new IllegalArgumentException("Chave desconhecida no mapa");
            return new LocalArenaMap(w,h,sx,sy,visuals,physical);
        } catch(IllegalArgumentException error) {throw new IOException("Mapa invalido: "+error.getMessage(),error);}
    }
    private static String take(Properties p,String key) {
        String value=(String)p.remove(key);if(value==null) throw new IllegalArgumentException("Chave ausente: "+key);return value;
    }
    private static int integer(Properties p,String key) {return Integer.parseInt(take(p,key));}
    private static float number(Properties p,String key) {return Float.parseFloat(take(p,key));}
    private static int count(Properties p,String key) {int n=integer(p,key);if(n<0 || n>4096) throw new IllegalArgumentException("Contagem invalida");return n;}
    /** Validador offline reutiliza exatamente o contrato carregado pelo jogo, sem abrir Swing. */
    public static void main(String[] args) {
        if(args.length!=1) throw new IllegalArgumentException("Uso: LocalArenaMap arquivo.properties");
        try {
            var map=load(Path.of(args[0]));
            System.out.println("VALIDO "+map.width()+"x"+map.height()+" spawn="+map.spawnX()+","+map.spawnY());
            for(int i=0;i<=10;i++) {final int layer=i;
                long count=map.visuals().stream().filter(v->v.layer()==layer).count();
                if(count>0) System.out.println("layer."+i+"="+count);
            }
            for(var category:CollisionCategory.values()) {
                long count=map.physical().stream().filter(p->p.category()==category).count();
                if(count>0) System.out.println(category+"="+count);
            }
        } catch(IOException | IllegalArgumentException error) {
            System.err.println("INVALIDO: "+error.getMessage());System.exit(1);
        }
    }
    /** Converte apenas descritores fisicos em obstaculos; borda pertence ao Space. */
    public List<CollisionService.Obstacle> obstacles() {
        return physical.stream().filter(p->p.category()!=CollisionCategory.WORLD_BOUNDARY)
                .map(p->new CollisionService.Obstacle(p.x(),p.y(),p.width(),p.height(),p.category())).toList();
    }
    /** Renderer de demonstracao usa tiles sinteticos em cache, sem ativar PNG candidato. */
    public Renderer renderer() {return new Renderer(this);}
    public static final class Renderer {
        private record Tile(Visual visual,BufferedImage image) { }
        private final List<Tile> tiles;
        private Renderer(LocalArenaMap map) {
            tiles=map.visuals().stream().sorted(java.util.Comparator.comparingInt(Visual::layer)).map(v->{
                BufferedImage image=new BufferedImage(32,32,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();
                g.setColor(new Color(v.rgb()));g.fillRect(0,0,32,32);g.setColor(new Color(v.rgb()).brighter());
                g.drawRect(0,0,31,31);g.drawLine(0,0,31,31);g.dispose();return new Tile(v,image);
            }).toList();
        }
        /** Renderiza somente dados imutaveis; nenhum efeito no mundo ou na hitbox. */
        public void draw(Graphics2D original) {
            drawLayers(original,0,10);
        }
        /** Camadas 0-4 ficam atrás dos atores; 5-10 ficam à frente, antes dos efeitos. */
        public void drawLayers(Graphics2D original,int first,int last) {
            Graphics2D g=(Graphics2D)original.create();
            try {
                g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
                for(var tile:tiles) {var v=tile.visual();
                    if(v.layer()>=first && v.layer()<=last && g.hitClip(v.x(),v.y(),v.width(),v.height()))
                        g.drawImage(tile.image(),v.x(),v.y(),v.width(),v.height(),null);}
                if(first==0) {g.setColor(Color.WHITE);g.drawString("MAPA LOCAL DE TESTE - TILES SINTETICOS",24,24);}
            }finally{g.dispose();}
        }
    }
}

package com.projetok.prototype;

import com.projetok.domain.skill.CryostasisService;
import com.projetok.domain.skill.LightningStepService;
import com.projetok.prototype.DebugSnapshot.SkillFeedbackKind;
import com.projetok.prototype.DebugSnapshot.SkillFeedbackView;
import com.projetok.prototype.DebugSnapshot.SkillHudView;
import com.projetok.prototype.DebugSnapshot.SkillState;

import java.util.Locale;

/**
 * Converte valores autoritativos em descrições imutáveis para o HUD.
 * Não consulta componentes mutáveis, não consome recursos e não executa habilidades.
 */
public final class SkillHudMapper {
    private static final SkillFeedbackView NONE = new SkillFeedbackView(SkillFeedbackKind.NONE, "", 0f);

    private SkillHudMapper() { }

    // --- Disponibilidade atual, independente do retorno temporário da última tentativa ---

    /** Descreve a disponibilidade atual da Criostase sem alterar o serviço. */
    public static SkillHudView cryostasis(boolean dead, float stamina, float cooldown,
                                          SkillFeedbackView feedback) {
        return map(CryostasisService.ID, "Q", "CRIOSTASE", CryostasisService.COST,
                dead, stamina, cooldown, false, false, feedback);
    }

    /** Distingue deslocamento ativo, espera por saída livre, recarga e falta de vigor. */
    public static SkillHudView lightningStep(boolean dead, float stamina, float cooldown,
                                             boolean active, boolean awaitingLanding,
                                             SkillFeedbackView feedback) {
        return map(LightningStepService.ID, "SHIFT", "PASSO RELAMPAGO", LightningStepService.COST,
                dead, stamina, cooldown, active, awaitingLanding, feedback);
    }

    /** Aplica uma ordem visual explícita sem interferir na elegibilidade do domínio. */
    private static SkillHudView map(String id, String key, String label, float cost, boolean dead,
                                    float stamina, float cooldown, boolean active,
                                    boolean awaitingLanding, SkillFeedbackView feedback) {
        SkillState state = dead ? SkillState.DEAD : awaitingLanding ? SkillState.AWAITING_LANDING
                : active ? SkillState.ACTIVE : cooldown > 0f ? SkillState.COOLDOWN
                : stamina < cost ? SkillState.INSUFFICIENT_STAMINA : SkillState.READY;
        String stateText = switch (state) {
            case DEAD -> "JOGADOR DERROTADO";
            case AWAITING_LANDING -> "AGUARDANDO SAIDA LIVRE";
            case ACTIVE -> String.format(Locale.ROOT, "EM MOVIMENTO | RECARGA %.1f s", cooldown);
            case COOLDOWN -> String.format(Locale.ROOT, "RECARGA %.1f s", cooldown);
            // O saldo exato fica no view/barra; arredondá-lo aqui poderia exibir
            // 35/35 para um float ainda abaixo do custo e contradizer a recusa.
            case INSUFFICIENT_STAMINA -> "VIGOR INSUFICIENTE";
            case READY -> "DISPONIVEL";
        };
        return new SkillHudView(id, key, label, cost, cooldown, stamina, state, stateText, feedback);
    }

    // --- Retornos breves conservam o motivo real retornado pelo domínio ---

    /** Retorna um marcador compartilhado e imutável de ausência de mensagem. */
    public static SkillFeedbackView none() { return NONE; }

    /** Converte exatamente o resultado do lançamento da Criostase. */
    public static SkillFeedbackView feedback(CryostasisService.Status status, float duration) {
        return message(switch (status) {
            case CAST -> SkillFeedbackKind.ACCEPTED;
            case INVALID -> SkillFeedbackKind.INVALID_TARGET;
            case DEAD -> SkillFeedbackKind.DEAD;
            case COOLDOWN -> SkillFeedbackKind.COOLDOWN;
            case STAMINA -> SkillFeedbackKind.INSUFFICIENT_STAMINA;
        }, duration);
    }

    /** Converte exatamente o resultado da tentativa do Passo Relâmpago. */
    public static SkillFeedbackView feedback(LightningStepService.Status status, float duration) {
        return message(switch (status) {
            case STARTED -> SkillFeedbackKind.ACCEPTED;
            case INVALID -> SkillFeedbackKind.INVALID_TARGET;
            case DEAD -> SkillFeedbackKind.DEAD;
            case ZERO_DIRECTION -> SkillFeedbackKind.ZERO_DIRECTION;
            case COOLDOWN -> SkillFeedbackKind.COOLDOWN;
            case STAMINA -> SkillFeedbackKind.INSUFFICIENT_STAMINA;
            case LANDING_PENDING -> SkillFeedbackKind.AWAITING_LANDING;
        }, duration);
    }

    /** Publica contato confirmado pela varredura seletiva, sem supor a geometria pelo alvo. */
    public static SkillFeedbackView blockedFeedback(float duration) {
        return message(SkillFeedbackKind.SOLID_OR_BOUNDARY, duration);
    }

    /** Avança somente uma cópia do relógio visual; o mundo chama uma vez por tick. */
    public static SkillFeedbackView elapse(SkillFeedbackView feedback, float dt) {
        float remaining = Math.max(0f, feedback.remaining() - dt);
        return remaining > 0f
                ? new SkillFeedbackView(feedback.kind(), feedback.message(), remaining) : NONE;
    }

    /** Associa cada motivo a uma mensagem curta, calculada antes da renderização. */
    private static SkillFeedbackView message(SkillFeedbackKind kind, float duration) {
        String message = switch (kind) {
            case NONE -> "";
            case ACCEPTED -> "ATIVADA";
            case INVALID_TARGET -> "RECUSADA: ALVO INVALIDO";
            case DEAD -> "RECUSADA: JOGADOR DERROTADO";
            case ZERO_DIRECTION -> "RECUSADA: DIRECAO ZERO";
            case COOLDOWN -> "RECUSADA: EM RECARGA";
            case INSUFFICIENT_STAMINA -> "RECUSADA: VIGOR INSUFICIENTE";
            case AWAITING_LANDING -> "RECUSADA: AGUARDANDO SAIDA";
            case SOLID_OR_BOUNDARY -> "BLOQUEIO: SOLIDO / BORDA";
        };
        return new SkillFeedbackView(kind, message, duration);
    }
}

package com.projetok.prototype;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.HexFormat;
import java.util.Map;
import java.util.Properties;
import javax.imageio.ImageIO;

/** Carrega uma vez a exportacao VALIDADO da TASK-013; sem IO por frame. */
public final class ValidatedSpriteAtlas {
    private final BufferedImage image;
    private final Map<String,int[]> frames;
    private final int pivotX, pivotY, offsetX, offsetY;
    private ValidatedSpriteAtlas(BufferedImage image, Map<String,int[]> frames, Properties p) {
        this.image=image; this.frames=Map.copyOf(frames);
        pivotX=Integer.parseInt(p.getProperty("pivotX")); pivotY=Integer.parseInt(p.getProperty("pivotY"));
        offsetX=Integer.parseInt(p.getProperty("offsetX")); offsetY=Integer.parseInt(p.getProperty("offsetY"));
        if (pivotX<0 || pivotX>64 || pivotY<0 || pivotY>64) throw new IllegalArgumentException("Pivot invalido");
        if(Math.abs((long)offsetX)>4096 || Math.abs((long)offsetY)>4096) throw new IllegalArgumentException("Offset excessivo");
    }
    /** Recusa status, hash, tamanho ou coordenadas inconsistentes antes de ativar o recurso. */
    public static ValidatedSpriteAtlas load(Path manifest) throws IOException {
        try { return loadChecked(manifest); }
        catch (IllegalArgumentException | NullPointerException error) { throw new IOException("Manifest visual invalido", error); }
    }
    /** Ausencia ou corrupcao opcional conserva o fallback, sem IO durante render. */
    public static ValidatedSpriteAtlas loadOptional(Path manifest) {
        if (!Files.exists(manifest)) return null;
        try { return load(manifest); }
        catch (IOException error) {
            System.err.println("[Spirit Gate] Pacote visual recusado; usando fallback: " + error.getMessage());
            return null;
        }
    }
    private static ValidatedSpriteAtlas loadChecked(Path manifest) throws IOException {
        if(Files.size(manifest)>1_000_000) throw new IOException("Manifest excessivo");
        Properties p=new Properties() {
            @Override public synchronized Object put(Object key,Object value) {
                if(containsKey(key)) throw new IllegalArgumentException("Chave visual duplicada");
                return super.put(key,value);
            }
        };
        try (var reader=Files.newBufferedReader(manifest)) { p.load(reader); }
        if (!"VALIDADO".equals(p.getProperty("status"))) throw new IOException("Asset sem validacao");
        boolean versioned=p.getProperty("packageVersion")!=null;
        if(versioned && (!"1".equals(p.getProperty("packageVersion")) ||
                !p.getProperty("assetId", "").matches("[a-z][a-z0-9._-]{0,63}") ||
                !"64".equals(p.getProperty("frameSize")) || !"32".equals(p.getProperty("tileSize")) ||
                p.getProperty("reviewOrigin", "").isBlank() ||
                !p.getProperty("sha256", "").equals(p.getProperty("approvedSha256"))))
            throw new IOException("Contrato versionado ou revisao invalida");
        Path png=manifest.toAbsolutePath().getParent().resolve(p.getProperty("image")).normalize();
        if(versioned && (!png.startsWith(manifest.toAbsolutePath().getParent()) || Files.isSymbolicLink(png)))
            throw new IOException("Caminho visual inseguro");
        if(!png.toRealPath().startsWith(manifest.toAbsolutePath().getParent().toRealPath()))
            throw new IOException("Caminho visual externo");
        if(Files.size(png)>16_000_000) throw new IOException("PNG excessivo");
        byte[] data=Files.readAllBytes(png);
        try {
            String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));
            if (!sha.equals(p.getProperty("sha256"))) throw new IOException("Hash de asset divergente");
        } catch (NoSuchAlgorithmException error) { throw new IllegalStateException(error); }
        // Inspeciona dimensões antes de alocar pixels, inclusive em PNG com hash correto.
        try(var input=ImageIO.createImageInputStream(new java.io.ByteArrayInputStream(data))) {
            var readers=ImageIO.getImageReaders(input);
            if(!readers.hasNext()) throw new IOException("Imagem ilegivel");
            var reader=readers.next();
            try {reader.setInput(input);
                int w=reader.getWidth(0),h=reader.getHeight(0);
                if(w>4096 || h>4096 || w<=0 || h<=0) throw new IOException("Dimensoes visuais excessivas");
            } finally {reader.dispose();}
        }
        BufferedImage image=ImageIO.read(new java.io.ByteArrayInputStream(data));
        if (image==null || image.getWidth()%64!=0 || image.getHeight()%64!=0) throw new IOException("Grade invalida");
        Map<String,int[]> frames=new HashMap<>();
        for (var state:DirectionalAnimation.State.values()) for (var direction:DirectionalAnimation.Direction.values()) {
            if (state==DirectionalAnimation.State.FAINT && direction!=DirectionalAnimation.Direction.FRONT) continue;
            for (int i=0;i<DirectionalAnimation.count(state);i++) {
                String key=key(state,direction,i), value=p.getProperty(key);
                if (value==null) {
                    if(versioned) throw new IOException("Pacote versionado incompleto");
                    continue; // contrato legado admite fallback por frame.
                }
                String[] parts=value.split(",");
                if(parts.length!=4) throw new IOException("Recorte invalido");
                int[] r=new int[4];
                try { for(int j=0;j<4;j++) r[j]=Integer.parseInt(parts[j]); }
                catch(NumberFormatException error) { throw new IOException("Coordenada invalida",error); }
                if(r[0]<0 || r[1]<0 || r[0]%64!=0 || r[1]%64!=0 || r[2]!=64 || r[3]!=64 || r[0]+64>image.getWidth() || r[1]+64>image.getHeight()) throw new IOException("Recorte fora da grade");
                for (int[] other:frames.values()) if(r[0]==other[0] && r[1]==other[1]) throw new IOException("Frames sobrepostos");
                frames.put(key,r);
            }
        }
        try { return new ValidatedSpriteAtlas(image,frames,p); }
        catch (IllegalArgumentException error) { throw new IOException("Metadados invalidos",error); }
    }
    private static String key(DirectionalAnimation.State state, DirectionalAnimation.Direction direction, int frame) {
        String action=switch(state) { case ATTACK -> "PUNCH"; case FAINT -> "KO"; default -> state.name(); };
        return action+"."+direction+"."+frame;
    }
    /** Retorna falso para preservar o desenho anterior quando falta qualquer frame. */
    public boolean draw(Graphics2D original, DebugSnapshot.ActorView actor, DirectionalAnimation.View view) {
        int[] r=frames.get(key(view.state(),view.direction(),view.frame()));
        if(r==null) return false;
        Graphics2D g=(Graphics2D)original.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
            int x=Math.round(actor.x())-pivotX+offsetX, y=Math.round(actor.y())-pivotY+offsetY;
            g.drawImage(image,x,y,x+64,y+64,r[0],r[1],r[0]+64,r[1]+64,null);
        } finally {g.dispose();}
        return true;
    }
}

