package com.projetok.prototype.rpg;
import com.projetok.rpg.*;
import javax.swing.*;
import java.awt.*;
/** Widgets consomem snapshots; botoes apenas enfileiram intencoes. */
final class RpgHud extends JPanel {
    private final JLabel status=new JLabel();
    private final JTextArea journal=new JTextArea(3,80);
    private final JPanel dialogue=new JPanel(new FlowLayout(FlowLayout.LEFT));
    private DialogueService.Node last;
    private final RpgRuntime runtime;
    RpgHud(RpgRuntime runtime) {super(new BorderLayout());this.runtime=runtime;add(status,BorderLayout.NORTH);add(dialogue,BorderLayout.CENTER);journal.setEditable(false);add(journal,BorderLayout.SOUTH);}
    void update(RpgWorld.View view) {
        journal.setText(view.journal().stream().map(q->q.name()+" | "+q.state()+" | "+q.progress()+"/"+q.required()+" - "+q.objective()).collect(java.util.stream.Collectors.joining("\n")));
        status.setText("  "+view.identity().name()+" | Nivel "+view.level()+" | XP "+view.state().xp()+" | Moedas "+view.state().coins()+" | Ataque "+view.attack()+" | Defesa "+view.defense()+" | "+view.state().region()+" | F: conversar  SPACE: atacar  Q: habilidade  1: pocao  F5: salvar");
        if(!java.util.Objects.equals(last,view.dialogue())) {
            last=view.dialogue();dialogue.removeAll();
            if(last!=null) {
                dialogue.add(new JLabel(last.text()));
                for(int i=0;i<last.choices().size();i++){int index=i;JButton button=new JButton(last.choices().get(i).text());button.addActionListener(e->runtime.command(w->w.choose(index)));dialogue.add(button);}
                JButton close=new JButton("Fechar");close.addActionListener(e->runtime.command(RpgWorld::closeDialogue));dialogue.add(close);
                if(view.activeNpc().equals("trader")) {
                    for(String id:new String[]{"potion","sword","robe"}){var item=new ItemCatalog(RpgContent.builtin()).get(id);JButton buy=new JButton("Comprar "+item.name()+" ("+item.price()+")");buy.addActionListener(e->runtime.command(w->w.trade(id,1,true)));dialogue.add(buy);}
                    JButton sell=new JButton("Vender cristal (1 moeda)");sell.addActionListener(e->runtime.command(w->w.trade("crystal",1,false)));dialogue.add(sell);
                }
            }
            revalidate();repaint();
        }
    }
}

package com.projetok.prototype.rpg;

import com.projetok.prototype.*;
import javax.swing.*;
import java.awt.event.*;
import java.util.List;

/** Entrada RPG explicita. A arena permanece acessivel pelo DebugLauncher original. */
public final class RpgLauncher {
    private RpgLauncher() { }
    public static void main(String[] args) {
        if(args.length==3&&args[0].equals("--smoke")){System.setProperty("spiritgate.smoke.name",args[1]);System.setProperty("spiritgate.smoke.output",args[2]);}
        else if(args.length!=0)throw new IllegalArgumentException("Uso: RpgLauncher [--smoke nome captura.png]");
        SwingUtilities.invokeLater(RpgLauncher::open);
    }
    static void open() {
        String name = System.getProperty("spiritgate.smoke.name");
        if(name==null)name=JOptionPane.showInputDialog(null, "Nome do personagem (3 a 24 caracteres)", "Criar personagem", JOptionPane.QUESTION_MESSAGE);
        if (name == null) return;
        com.projetok.rpg.CharacterIdentity identity;
        try { identity = com.projetok.rpg.CharacterIdentity.create(name, "guardian", "azure"); }
        catch (IllegalArgumentException error) { JOptionPane.showMessageDialog(null, error.getMessage()); open(); return; }
        RpgRuntime runtime = new RpgRuntime(new com.projetok.rpg.RpgWorld(identity));
        DebugSnapshot template = DebugWorld.demo().snapshot();
        DebugPanel panel = new DebugPanel(() -> adapt(runtime.snapshot(), template));
        panel.setLocalMap(RpgMaps.region("village"));
        JFrame frame = new JFrame("Spirit Gate | RPG offline");
        JPanel root=new JPanel(new java.awt.BorderLayout());RpgHud hud=new RpgHud(runtime);root.add(panel,java.awt.BorderLayout.CENTER);root.add(hud,java.awt.BorderLayout.SOUTH);
        frame.setContentPane(root); frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
        frame.pack(); frame.setLocationRelativeTo(null);
        var screen=java.awt.Toolkit.getDefaultToolkit().getScreenSize();frame.setSize(Math.min(1260,screen.width-60),Math.min(900,screen.height-80));frame.setLocationRelativeTo(null);
        boolean[] held = new boolean[4];
        bind(panel,"F",()->runtime.command(w->w.interact()));
        bind(panel,"SPACE",()->runtime.command(w->w.attack()));
        bind(panel,"Q",()->runtime.command(w->w.castAbility()));
        bind(panel,"ESCAPE",()->runtime.command(w->w.closeDialogue()));
        bind(panel,"R",()->runtime.command(w->w.returnHome()));
        bind(panel,"1",()->runtime.command(w->w.use("potion")));
        bind(panel,"F5",()->runtime.save(new com.projetok.rpg.LocalSaveStore(java.nio.file.Path.of("saves","offline.properties"))).whenComplete((unused,error)->SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(frame,error==null?"Progresso salvo":"Falha ao salvar: "+error.getMessage()))));
        String[] keys = {"W", "S", "A", "D"};
        for (int i = 0; i < keys.length; i++) {
            final int key = i;
            for (boolean down : new boolean[]{true, false}) {
                String id = keys[i] + down;
                panel.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke((down ? "pressed " : "released ") + keys[i]), id);
                panel.getActionMap().put(id, new AbstractAction() {
                    public void actionPerformed(ActionEvent e) { held[key] = down; runtime.input((held[3]?1:0)-(held[2]?1:0), (held[1]?1:0)-(held[0]?1:0)); }
                });
            }
        }
        String[] displayedRegion={"village"};
        Timer timer = new Timer(33, e -> {var view=runtime.snapshot();panel.setAmbientLight(com.projetok.rpg.EnvironmentCycle.light(view.ticks(),true));if(!displayedRegion[0].equals(view.state().region())){displayedRegion[0]=view.state().region();panel.setLocalMap(RpgMaps.region(displayedRegion[0]));}panel.repaint();hud.update(view);});
        frame.addWindowListener(new WindowAdapter() { public void windowClosed(WindowEvent e) { timer.stop(); runtime.close(); } });
        frame.addWindowFocusListener(new WindowAdapter() { public void windowLostFocus(WindowEvent e) { java.util.Arrays.fill(held, false); runtime.input(0, 0); } });
        runtime.start(); timer.start(); frame.setVisible(true);
        if(System.getProperty("spiritgate.smoke.output")!=null){Timer capture=new Timer(2000,e->{
            java.awt.Rectangle bounds=frame.getBounds();new Thread(()->{try{var image=new java.awt.Robot().createScreenCapture(bounds);javax.imageio.ImageIO.write(image,"png",new java.io.File(System.getProperty("spiritgate.smoke.output")));}catch(Exception error){error.printStackTrace();}finally{SwingUtilities.invokeLater(frame::dispose);}},"rpg-smoke").start();
        });capture.setRepeats(false);capture.start();}
    }
    static DebugSnapshot adapt(com.projetok.rpg.RpgWorld.View v, DebugSnapshot t) {
        var actors=new java.util.ArrayList<DebugSnapshot.ActorView>();
        actors.add(new DebugSnapshot.ActorView(1,v.identity().name(),v.x(),v.y(),18,v.state().hp(),v.maxHp(),true,v.state().hp()>0));
        for(var enemy:v.enemies())actors.add(new DebugSnapshot.ActorView(enemy.id(),enemy.name(),enemy.x(),enemy.y(),19,enemy.hp(),enemy.maxHp(),false,enemy.hp()>0));
        int npcId=500;for(var npc:v.npcs())actors.add(new DebugSnapshot.ActorView(npcId++,npc.name()+" [F]",npc.x(),npc.y(),16,1,1,false,true));
        for(var portal:v.portals())actors.add(new DebugSnapshot.ActorView(npcId++,"[F] "+portal.destination(),portal.x(),portal.y(),22,1,1,false,true));
        for(var object:v.objects())if(object.available())actors.add(new DebugSnapshot.ActorView(npcId++,"[F] "+object.id(),object.x(),object.y(),15,1,1,false,true));
        var warnings=v.enemies().stream().filter(e->e.state().equals("PREPARE")).map(e->new DebugSnapshot.IceZoneView(e.x(),e.y(),e.hp()*2<=e.maxHp()?135:110,0,1)).toList();
        return new DebugSnapshot(actors,
            List.of(new DebugSnapshot.Obstacle(380,180,120,120)),List.of(),v.state().hp(),v.maxHp(),0,v.state().hp()==0,v.ticks(),v.message(),1,0,0,null,
            100,100,0,warnings,List.of(),false,0,0,List.of(),false,List.of(),t.cryostasisHud(),t.lightningStepHud());
    }
    static void bind(JComponent component,String key,Runnable action) {
        boolean[] held={false};
        for(boolean down:new boolean[]{true,false}) {
            String id=key+down;
            component.getInputMap(JComponent.WHEN_IN_FOCUSED_WINDOW).put(KeyStroke.getKeyStroke((down?"pressed ":"released ")+key),id);
            component.getActionMap().put(id,new AbstractAction(){public void actionPerformed(ActionEvent e){if(down&&!held[0])action.run();held[0]=down;}});
        }
    }
}

package com.projetok.prototype.rpg;
import com.projetok.prototype.*;
import com.projetok.domain.movement.CollisionCategory;
import java.util.*;
/** Autoria sintetica reutilizando o mapa e renderer ja existentes. */
public final class RpgMaps {
