package com.projetok.domain.entity.component;

/** Vigor físico fracionário, sempre finito e no intervalo de zero ao máximo. */
public final class StaminaComponent implements Component {
    private final float maximum;
    private float current;

    /** Cria o recurso cheio com o valor provisório de 100 pontos. */
    public StaminaComponent() {
        this(100f);
    }

    /** Cria o recurso cheio; o máximo deve ser finito e estritamente positivo. */
    public StaminaComponent(float maximum) {
        if (!Float.isFinite(maximum) || maximum <= 0f)
            throw new IllegalArgumentException("Vigor máximo deve ser finito e positivo");
        this.maximum = maximum;
        this.current = maximum;
    }

    /** Retorna o vigor disponível. */
    public float current() { return current; }

    /** Retorna o limite do recurso. */
    public float max() { return maximum; }

    /** Consome somente se houver saldo; custo inválido lança exceção sem mutação. */
    public boolean tryConsume(float cost) {
        validateAmount(cost);
        if (cost > current) return false;
        current -= cost;
        return true;
    }

    /** Restaura uma quantidade finita e não negativa, sem ultrapassar o máximo. */
    public void restore(float amount) {
        validateAmount(amount);
        current = (float) Math.min(maximum, (double) current + amount);
    }

    /** Valida uma quantidade antes de qualquer alteração de estado. */
    private static void validateAmount(float amount) {
        if (!Float.isFinite(amount) || amount < 0f)
            throw new IllegalArgumentException("Quantidade de vigor deve ser finita e não negativa");
    }
}

package com.projetok.domain.entity.component;

import com.projetok.domain.race.AttributeGrowth;

/**
 * Sucessora dos campos strength/inteligency/agility soltos em Entity.java, mais o "points"
 * que hoje vive implícito. unspentPoints são os pontos livres que o jogador aloca manualmente
 * (spendOnX) — separados do bônus racial automático (applyLevelUp), que nunca é "gasto".
 */
public record StatsComponent(int strength, int intelligence, int agility, int level, int unspentPoints)
    implements Component {

    public StatsComponent {
        if (level < 1) throw new IllegalArgumentException("level deve ser >= 1");
        if (unspentPoints < 0) throw new IllegalArgumentException("unspentPoints não pode ser negativo");
    }

    /** pointsGained vem de LevelingRules; racialGrowth vem de Race.growthBonus() — automático, não gasto. */
    public StatsComponent applyLevelUp(int pointsGained, AttributeGrowth racialGrowth) {
        return new StatsComponent(
            strength + racialGrowth.strength(),
            intelligence + racialGrowth.intelligence(),
            agility + racialGrowth.agility(),
            level + 1,
            unspentPoints + pointsGained
        );
    }

    public StatsComponent spendOnStrength() {
        requirePoints();
        return new StatsComponent(strength + 1, intelligence, agility, level, unspentPoints - 1);
    }

    public StatsComponent spendOnIntelligence() {
        requirePoints();
        return new StatsComponent(strength, intelligence + 1, agility, level, unspentPoints - 1);
    }

    public StatsComponent spendOnAgility() {
        requirePoints();
        return new StatsComponent(strength, intelligence, agility + 1, level, unspentPoints - 1);
    }

    private void requirePoints() {
        if (unspentPoints <= 0) {
            throw new IllegalStateException("Sem pontos de atributo disponíveis para gastar.");
        }
    }
}

package com.projetok.domain.entity.component;

import com.projetok.domain.effect.StatusEffectType;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;

/**
 * Guarda os efeitos e seus segundos restantes por entidade, sem regras de habilidade.
 * Somente a thread proprietária da entidade modifica este componente.
 */
public final class StatusEffectsComponent implements Component {
    private static final double EXPIRATION_TOLERANCE = 0.000001;
    private final EnumMap<StatusEffectType, Double> remaining = new EnumMap<>(StatusEffectType.class);

    /** Cria armazenamento sem efeitos ativos. */
    public StatusEffectsComponent() { }

    /** Informa se o tipo está ativo, sem modificar seu temporizador. */
    public boolean has(StatusEffectType type) {
        return remaining.containsKey(Objects.requireNonNull(type, "type"));
    }

    /** Retorna segundos restantes, ou zero quando o efeito não está ativo. */
    public float remaining(StatusEffectType type) {
        return remaining.getOrDefault(Objects.requireNonNull(type, "type"), 0.0).floatValue();
    }

    /** Publica uma cópia imutável dos temporizadores, sem expor o mapa interno. */
    public Map<StatusEffectType, Double> snapshot() {
        return Map.copyOf(remaining);
    }

    // --- Armazenamento e avanço do tempo ---

    /** Substitui a duração por um valor finito positivo, sem acumular o tempo anterior. */
    public void refresh(StatusEffectType type, float duration) {
        Objects.requireNonNull(type, "type");
        if (!Float.isFinite(duration) || duration <= 0f)
            throw new IllegalArgumentException("Duração do efeito deve ser finita e positiva");
        remaining.put(type, (double) duration);
    }

    /** Avança todos os efeitos; tolerância de um microssegundo evita resíduos de deltas float. */
    public void advance(float dt) {
        if (!Float.isFinite(dt) || dt < 0f)
            throw new IllegalArgumentException("Delta do efeito deve ser finito e não negativo");
        remaining.replaceAll((type, seconds) -> seconds - dt);
        remaining.values().removeIf(seconds -> seconds <= EXPIRATION_TOLERANCE);
    }

    /** Remove todos os efeitos, por exemplo após a morte do portador. */
    public void clear() {
        remaining.clear();
    }
}

package com.projetok.domain.combat.style;

import com.projetok.domain.combat.CombatStyle;
import com.projetok.domain.entity.component.StatsComponent;
import com.projetok.domain.race.DamageType;

/**
 * Estilo de combate padrão usado quando nenhum estilo especial foi escolhido para uma entidade.
 *
 * <p>Equivale, em espírito, à intenção original de "sword null" em Human.java — a ideia de
 * que um personagem pode atacar sem estar armado. A diferença é que aqui isso é modelado
 * como um {@link CombatStyle} de verdade, e não como um campo esquecido/nulo: o dano nunca
 * some, ele só passa a vir 100% dos atributos do personagem em vez de vir de uma arma.</p>
 *
 * <p>{@link com.projetok.domain.entity.component.CombatComponent} usa esta classe
 * automaticamente como fallback sempre que é construído ou atualizado com {@code style =
 * null} — nenhuma outra classe do domínio precisa instanciar {@code UnarmedStrike}
 * manualmente, a menos que queira usá-lo explicitamente (ex.: um NPC que só briga
 * desarmado, de propósito).</p>
 */
public final class UnarmedStrike implements CombatStyle {

    /**
     * Calcula o dano do golpe desarmado.
     *
     * <p>Fórmula: metade da força do atacante, sem nenhum bônus de arma ou item —
     * propositalmente simples, para servir de "piso" de dano que qualquer personagem
     * consegue causar mesmo sem equipamento nenhum.</p>
     *
     * @param stats atributos atuais do atacante; só {@code strength()} é usado aqui
     * @return dano calculado (>= 0, assumindo strength >= 0)
     */
    @Override
    public int computeDamage(StatsComponent stats) {
        return stats.strength() / 2;
    }

    /**
     * @return {@link DamageType#PHYSICAL} — golpe desarmado nunca causa dano elemental
     */
    @Override
    public DamageType damageType() {
        return DamageType.PHYSICAL;
    }

    /**
     * @return "Ataque Desarmado" — nome exibido ao jogador (ex.: em log de combate)
     */
    @Override
    public String displayName() {
        return "Ataque Desarmado";
    }

    /**
     * @return 0 — atacar desarmado não custa recurso nenhum; é a ação "de base" que todo
     * personagem sempre tem disponível, mesmo sem stamina
     */
    @Override
    public int staminaCost() {
        return 0;
    }
}

package com.projetok.domain.combat.style;

import com.projetok.domain.combat.CombatStyle;
import com.projetok.domain.entity.component.StatsComponent;
import com.projetok.domain.race.DamageType;

/**
 * Reescrita de WaterStyle.java original. O bug antigo (executeAttack -> damagetaken() ->
 * throw new UnsupportedOperationException) foi removido: o estilo só CALCULA dano, nunca
 * causa efeito colateral sozinho — quem aplica dano de fato é sempre o CombatService.
 */
public final class WaterStyle implements CombatStyle {

    private static final int STAMINA_COST = 20;
    private static final int BASE_DAMAGE = 50;

    @Override
    public int computeDamage(StatsComponent stats) {
        return BASE_DAMAGE + (stats.agility() / 2);
    }

    @Override
    public DamageType damageType() {
        return DamageType.WATER;
    }

    @Override
    public String displayName() {
        return "Arte da Água";
    }

    @Override
    public int staminaCost() {
        return STAMINA_COST;
    }
}
